<body>
  <div class="topbar">
    <div class="brand">
      <div class="brand-icon">DB</div>
      <div>
        <div class="brand-title">CareerPulse — Real-Time PostgreSQL Database Monitor</div>
        <div class="brand-sub" id="last-sync-label">Connecting to live PostgreSQL audit stream...</div>
      </div>
    </div>
    <div class="controls">
      <div class="live-pill" id="live-status-pill">
        <span class="pulse-dot"></span>
        <span id="live-status-text">LIVE STREAMING (2s)</span>
      </div>
      <button class="btn" id="toggle-live-btn" onclick="toggleLivePolling()">⏸ Pause</button>
      <select class="select-ctrl" id="poll-interval-sel" onchange="changePollInterval(this.value)">
        <option value="2000" selected>Poll: Every 2s</option>
        <option value="5000">Poll: Every 5s</option>
        <option value="10000">Poll: Every 10s</option>
      </select>
      <button class="btn btn-primary" onclick="fetchMonitorData(true)">🔄 Refresh Now</button>
      <a class="btn" href="/webhook/job-dashboard?mode=mobile" target="_blank">📱 Open Mobile App ↗</a>
    </div>
  </div>

  <div class="kpi-strip" id="kpi-strip"></div>

  <div class="main-grid">
    <!-- Left Column: Real-Time Database Audit Stream -->
    <div class="panel">
      <div class="panel-header">
        <div class="panel-title">
          <span>⚡ Real-Time Database Activity Stream (database_audit_log)</span>
          <span class="badge op-INSERT" id="audit-count-badge">0 events</span>
        </div>
        <div style="font-size:11px;color:var(--text-muted);">
          Captures every INSERT, UPDATE, DELETE &amp; API mutation via PostgreSQL row triggers
        </div>
      </div>
      <div class="filter-bar">
        <select class="select-ctrl" id="filter-table" onchange="renderAuditStream()">
          <option value="ALL">All Tables &amp; Actions</option>
          <option value="learned_rules">learned_rules (CV/CL/Chat Rules)</option>
          <option value="resume_generations">resume_generations (CVs)</option>
          <option value="cover_letter_generations">cover_letter_generations (CLs)</option>
          <option value="job_applications">job_applications (559 Jobs)</option>
          <option value="master_resume_state">master_resume_state</option>
          <option value="linkedin_activity_log">linkedin_activity_log</option>
          <option value="linkedin_network_contacts">linkedin_network_contacts</option>
          <option value="portal_credentials_vault">portal_credentials_vault</option>
        </select>
        <select class="select-ctrl" id="filter-op" onchange="renderAuditStream()">
          <option value="ALL">All Operations</option>
          <option value="INSERT">INSERT Only</option>
          <option value="UPDATE">UPDATE Only</option>
          <option value="DELETE">DELETE Only</option>
          <option value="API_CALL">API_CALL Only</option>
        </select>
        <select class="select-ctrl" id="filter-decision" onchange="renderAuditStream()">
          <option value="ALL">All Decisions (Approved / Rejected / Other)</option>
          <option value="APPROVED">✅ Approved / Applied Only</option>
          <option value="REJECTED">🚫 Rejected / Skipped / Hold Only</option>
          <option value="PENDING">⏳ Pending / Reworked Only</option>
        </select>
        <input type="text" class="search-ctrl" id="filter-search" style="flex:1;min-width:160px;" placeholder="Search table, company, rule ID, column, or SQL..." oninput="renderAuditStream()" />
      </div>
      <div class="panel-body" id="audit-stream-body">
        <div style="padding:30px;text-align:center;color:var(--text-muted);">Loading real-time PostgreSQL audit events...</div>
      </div>
    </div>

    <!-- Right Column: Live Table Inspector -->
    <div class="panel">
      <div class="panel-header">
        <div class="panel-title">
          <span>🗄️ Live PostgreSQL Table Inspector</span>
        </div>
        <div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap;">
          <select class="select-ctrl" id="table-decision-filter" onchange="renderTableInspector()">
            <option value="ALL">All Statuses</option>
            <option value="APPROVED">✅ Approved / Applied</option>
            <option value="REJECTED">🚫 Rejected / Skipped / Hold</option>
            <option value="PENDING">⏳ Pending Review</option>
          </select>
          <input type="text" class="search-ctrl" id="table-search" style="width:180px;" placeholder="Filter table rows..." oninput="renderTableInspector()" />
        </div>
      </div>
      <div class="tab-strip" id="table-tabs"></div>
      <div class="panel-body" id="table-inspector-body" style="padding:0;"></div>
    </div>
  </div>

  <script>
    let monitorState = null;
    let isLive = true;
    let pollMs = 4000;
    let isFetchingMonitor = false;
    let pollTimer = null;
    let seenEventIds = new Set();
    let newlyArrivedIds = new Set();
    let isFirstLoad = true;
    let activeTableTab = 'learned_rules';
    let expandedDiffMap = {};
    let expandedSqlMap = {};

    function classifyDecisionFromText(raw) {
      const s = String(raw || '').toLowerCase();
      if (/\b(rejected|reject|skipped|skip|hold \/ skip|on hold|deleted)\b/.test(s) || /"subaction"\s*:\s*"(reject|skip|hold)"/.test(s)) {
        return { code: 'REJECTED', label: '🚫 REJECTED / SKIPPED', cls: 'dec-rejected' };
      }
      if (/\b(approved|apr_res|apr_cl|apr_res_cl|approve_and_cl|applied|offer received|interviewing|sent|confirmed)\b/.test(s)) {
        if (/\bapplied\b/.test(s) && !/\bapproved\b/.test(s)) {
          return { code: 'APPROVED', label: '🚀 APPLIED', cls: 'dec-approved' };
        }
        return { code: 'APPROVED', label: '✅ APPROVED', cls: 'dec-approved' };
      }
      if (/\b(pending|reworked|generated|tracking|draft)\b/.test(s)) {
        return { code: 'PENDING', label: '⏳ PENDING / DRAFT', cls: 'dec-pending' };
      }
      return null;
    }

    function esc(s) {
      return String(s ?? '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');
    }

    async function fetchMonitorData(manual) {
      if (isFetchingMonitor && !manual) return;
      isFetchingMonitor = true;
      try {
        const resp = await fetch('/webhook/job-dashboard-api', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ action: 'db_monitor' })
        });
        if (!resp.ok) return;
        const data = await resp.json();
        if (!data || !data.ok) return;

        const logs = Array.isArray(data.auditLogs) ? data.auditLogs : [];
        if (isFirstLoad) {
          logs.forEach(l => seenEventIds.add(Number(l.id)));
          isFirstLoad = false;
        } else {
          logs.forEach(l => {
            const numId = Number(l.id);
            if (!seenEventIds.has(numId)) {
              seenEventIds.add(numId);
              newlyArrivedIds.add(numId);
            }
          });
        }

        monitorState = data;
        const syncEl = document.getElementById('last-sync-label');
        if (syncEl) {
          syncEl.textContent = 'Last synced: ' + (data.timestamp || new Date().toLocaleTimeString()) + ' • Connected to Hostinger PostgreSQL';
        }
        renderKpis();
        renderAuditStream();
        renderTableTabs();
        renderTableInspector();
      } catch (e) {
        console.error('Monitor poll error:', e);
      } finally {
        isFetchingMonitor = false;
      }
    }

    function renderKpis() {
      if (!monitorState || !monitorState.tableCounts) return;
      const c = monitorState.tableCounts;
      const dc = monitorState.decisionCounts || {};
      const items = [
        { key: 'ALL', label: 'Audit Log Events', val: c.audit_events || 0, sub: 'Real-time trigger stream', tab: null, dec: 'ALL' },
        { key: 'job_applications', label: '✅ Approved / Applied', val: dc.jobsApprovedOrApplied || 0, sub: 'Approved & Applied Jobs', tab: 'job_applications', dec: 'APPROVED' },
        { key: 'job_applications', label: '🚫 Rejected / Hold', val: dc.jobsRejectedOrHold || 0, sub: 'Rejected or Skipped Jobs', tab: 'job_applications', dec: 'REJECTED' },
        { key: 'job_applications', label: '⏳ Pending Review', val: dc.jobsPending || 0, sub: 'Jobs awaiting decision', tab: 'job_applications', dec: 'PENDING' },
        { key: 'learned_rules', label: 'learned_rules', val: c.learned_rules || 0, sub: 'Active CV/CL/Chat rules', tab: 'learned_rules', dec: 'ALL' },
        { key: 'resume_generations', label: 'resume_generations', val: c.resume_generations || 0, sub: 'Stored 1-Page CVs', tab: 'resume_generations', dec: 'ALL' },
        { key: 'cover_letter_generations', label: 'cover_letter_gens', val: c.cover_letter_generations || 0, sub: 'Stored 1-Page CLs', tab: 'cover_letter_generations', dec: 'ALL' },
        { key: 'linkedin_activity_log', label: 'LinkedIn ✅ / 🚫', val: `${dc.liApproved || 0} / ${dc.liRejected || 0}`, sub: 'Approved vs Rejected LI', tab: 'linkedin_activity_log', dec: 'ALL' }
      ];
      const curFilter = document.getElementById('filter-table')?.value || 'ALL';
      document.getElementById('kpi-strip').innerHTML = items.map(it => `
        <div class="kpi-card ${curFilter === it.key ? 'active' : ''}" onclick="selectKpiTable('${it.key}', '${it.tab || ''}')">
          <div class="kpi-label">${esc(it.label)}</div>
          <div class="kpi-val">${esc(it.val)}</div>
          <div class="kpi-sub">${esc(it.sub)}</div>
        </div>
      `).join('');
    }

    function selectKpiTable(filterKey, tabName, decFilter) {
      const sel = document.getElementById('filter-table');
      if (sel) sel.value = filterKey;
      const decSel = document.getElementById('filter-decision');
      if (decSel && decFilter) decSel.value = decFilter;
      const tblDecSel = document.getElementById('table-decision-filter');
      if (tblDecSel && decFilter) tblDecSel.value = decFilter;
      if (tabName) activeTableTab = tabName;
      renderKpis();
      renderAuditStream();
      renderTableTabs();
      renderTableInspector();
    }

    function toggleDiff(id) {
      expandedDiffMap[id] = !expandedDiffMap[id];
      renderAuditStream();
    }

    function toggleSql(id) {
      expandedSqlMap[id] = !expandedSqlMap[id];
      renderAuditStream();
    }

    function formatChangedFieldsHtml(cf) {
      if (!cf || typeof cf !== 'object') return '';
      const keys = Object.keys(cf);
      if (keys.length === 0) return '';
      return keys.map(k => {
        const val = cf[k];
        if (val && typeof val === 'object' && ('old' in val || 'new' in val)) {
          return `<div class="diff-row"><span class="diff-col">${esc(k)}:</span> <span class="diff-old">${esc(val.old)}</span> &rarr; <span class="diff-new">${esc(val.new)}</span></div>`;
        }
        const strVal = typeof val === 'object' ? JSON.stringify(val, null, 2) : String(val);
        return `<div class="diff-row"><span class="diff-col">${esc(k)}:</span> <span class="diff-new">${esc(strVal.slice(0, 600))}</span></div>`;
      }).join('');
    }

    function renderAuditStream() {
      if (!monitorState) return;
      const logs = Array.isArray(monitorState.auditLogs) ? monitorState.auditLogs : [];
      const tblFilter = document.getElementById('filter-table')?.value || 'ALL';
      const opFilter = document.getElementById('filter-op')?.value || 'ALL';
      const decFilter = document.getElementById('filter-decision')?.value || 'ALL';
      const q = (document.getElementById('filter-search')?.value || '').trim().toLowerCase();

      const filtered = logs.filter(item => {
        if (tblFilter !== 'ALL' && item.table_name !== tblFilter) return false;
        if (opFilter !== 'ALL' && item.operation !== opFilter) return false;
        if (decFilter !== 'ALL') {
          const dec = classifyDecisionFromText(`${item.summary || ''} ${JSON.stringify(item.changed_fields || {})}`);
          if (!dec || dec.code !== decFilter) return false;
        }
        if (q) {
          const hay = `${item.table_name || ''} ${item.operation || ''} ${item.record_id || ''} ${item.summary || ''} ${JSON.stringify(item.changed_fields || {})} ${item.sql_query || ''}`.toLowerCase();
          if (!hay.includes(q)) return false;
        }
        return true;
      });

      const badgeEl = document.getElementById('audit-count-badge');
      if (badgeEl) badgeEl.textContent = `${filtered.length} events`;

      const container = document.getElementById('audit-stream-body');
      if (filtered.length === 0) {
        container.innerHTML = `<div style="padding:32px;text-align:center;color:var(--text-muted);">No matching database audit events found. Perform any action in the app to watch it appear here live!</div>`;
        return;
      }

      container.innerHTML = filtered.map(item => {
        const id = Number(item.id);
        const isNew = newlyArrivedIds.has(id);
        const showDiff = Boolean(expandedDiffMap[id]);
        const showSql = Boolean(expandedSqlMap[id]);
        const diffHtml = formatChangedFieldsHtml(item.changed_fields);
        return `
          <div class="event-card ${isNew ? 'new-flash' : ''}">
            <div class="event-top">
              <div style="display:flex;align-items:center;gap:7px;flex-wrap:wrap;">
                <span class="badge op-${esc(item.operation || 'UPDATE')}">${esc(item.operation || 'EVENT')}</span>
                <span class="tbl-badge">${esc(item.table_name || 'postgres')}</span>
                <span class="rec-badge">${esc(item.record_id || '')}</span>
                ${(() => {
                  const dec = classifyDecisionFromText(`${item.summary || ''} ${JSON.stringify(item.changed_fields || {})}`);
                  return dec ? `<span class="${dec.cls}">${dec.label}</span>` : '';
                })()}
                ${isNew ? `<span class="badge op-INSERT" style="background:#10b981;color:#060a12;">● NEW LIVE</span>` : ''}
              </div>
              <div class="time-str">#${esc(id)} • ${esc(item.ist_time || item.event_time || '')} IST</div>
            </div>
            <div class="event-summary">${esc(item.summary || '')}</div>
            <div style="display:flex;gap:8px;margin-top:8px;flex-wrap:wrap;">
              ${diffHtml ? `<button class="btn" style="padding:4px 9px;font-size:10.5px;" onclick="toggleDiff(${id})">${showDiff ? '▾ Hide Column Diff / Payload' : '▸ View Column Diff / Payload'}</button>` : ''}
              ${item.sql_query ? `<button class="btn" style="padding:4px 9px;font-size:10.5px;" onclick="toggleSql(${id})">${showSql ? '▾ Hide SQL Query' : '▸ View SQL Query'}</button>` : ''}
            </div>
            ${showDiff && diffHtml ? `<div class="details-box">${diffHtml}</div>` : ''}
            ${showSql && item.sql_query ? `<div class="details-box" style="color:#93c5fd;">${esc(item.sql_query)}</div>` : ''}
          </div>
        `;
      }).join('');
    }

    function renderTableTabs() {
      if (!monitorState || !monitorState.tables) return;
      const tabs = [
        { key: 'learned_rules', label: 'learned_rules' },
        { key: 'resume_generations', label: 'resume_generations' },
        { key: 'cover_letter_generations', label: 'cover_letter_gens' },
        { key: 'job_applications', label: 'job_applications' },
        { key: 'master_resume_state', label: 'master_resume_state' },
        { key: 'linkedin_activity_log', label: 'linkedin_activity_log' },
        { key: 'linkedin_network_contacts', label: 'network_contacts' },
        { key: 'portal_credentials_vault', label: 'credentials_vault' }
      ];
      document.getElementById('table-tabs').innerHTML = tabs.map(t => `
        <button class="tab-btn ${activeTableTab === t.key ? 'active' : ''}" onclick="activeTableTab='${t.key}';renderTableTabs();renderTableInspector();">
          ${esc(t.label)} (${(monitorState.tables[t.key] || []).length})
        </button>
      `).join('');
    }

    function renderTableInspector() {
      if (!monitorState || !monitorState.tables) return;
      const rows = monitorState.tables[activeTableTab] || [];
      const q = (document.getElementById('table-search')?.value || '').trim().toLowerCase();
      const decFilter = document.getElementById('table-decision-filter')?.value || 'ALL';
      const filtered = rows.filter(r => {
        if (q && !JSON.stringify(r).toLowerCase().includes(q)) return false;
        if (decFilter !== 'ALL') {
          const statusStr = `${r.status || ''} ${r.resume_status || ''} ${r.cl_status || ''} ${r.approval_status || ''} ${r.execution_status || ''} ${r.auth_status || ''}`;
          const dec = classifyDecisionFromText(statusStr);
          if (!dec || dec.code !== decFilter) return false;
        }
        return true;
      });
      const body = document.getElementById('table-inspector-body');
      if (filtered.length === 0) {
        body.innerHTML = `<div style="padding:28px;text-align:center;color:var(--text-muted);">No rows match filter in ${esc(activeTableTab)}.</div>`;
        return;
      }
      const cols = Object.keys(filtered[0]);
      body.innerHTML = `
        <table class="data-table">
          <thead>
            <tr>${cols.map(c => `<th>${esc(c)}</th>`).join('')}</tr>
          </thead>
          <tbody>
            ${filtered.map(r => `
              <tr>
                ${cols.map(c => {
                  const rawVal = r[c];
                  const strVal = typeof rawVal === 'object' && rawVal !== null ? JSON.stringify(rawVal) : String(rawVal ?? '');
                  if (/status/i.test(c) && strVal) {
                    const dec = classifyDecisionFromText(strVal);
                    if (dec) {
                      return `<td><span class="${dec.cls}">${esc(strVal)}</span></td>`;
                    }
                  }
                  return `<td>${esc(strVal.length > 220 ? strVal.slice(0, 220) + '...' : strVal)}</td>`;
                }).join('')}
              </tr>
            `).join('')}
          </tbody>
        </table>
      `;
    }

    function toggleLivePolling() {
      isLive = !isLive;
      const pill = document.getElementById('live-status-pill');
      const txt = document.getElementById('live-status-text');
      const btn = document.getElementById('toggle-live-btn');
      if (isLive) {
        pill.classList.remove('paused');
        txt.textContent = `LIVE STREAMING (${pollMs / 1000}s)`;
        btn.textContent = '⏸ Pause';
        startPolling();
      } else {
        pill.classList.add('paused');
        txt.textContent = 'PAUSED';
        btn.textContent = '▶ Resume';
        if (pollTimer) clearInterval(pollTimer);
      }
    }

    function changePollInterval(val) {
      pollMs = Number(val) || 2000;
      if (isLive) {
        document.getElementById('live-status-text').textContent = `LIVE STREAMING (${pollMs / 1000}s)`;
        startPolling();
      }
    }

    function startPolling() {
      if (pollTimer) clearInterval(pollTimer);
      pollTimer = setInterval(() => {
        if (isLive && document.visibilityState !== 'hidden') {
          fetchMonitorData(false);
        }
      }, pollMs);
    }

    fetchMonitorData(true);
    startPolling();
  </script>
</body>
</html>", contentType: 'text/html; charset=utf-8' } }];
}

