    /* 3. BURGER MENU NAVIGATION DRAWER (REPLACES CLUTTERED TOP TAB ROW) */
    .burger-btn {
      width: 34px;
      height: 34px;
      border-radius: 9px;
      border: 1px solid var(--border-color);
      background: var(--bg-surface-2);
      color: var(--text-main);
      display: inline-flex;
      align-items: center;
      justify-content: center;
      font-size: 16px;
      cursor: pointer;
      transition: all 0.18s ease;
      flex-shrink: 0;
