    /* Sub-Tab Segmented Bar (Opaque & Clean — No Scroll Bleed Behind Banner) */
    .seg-bar {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 5px;
      background: var(--bg-surface);
      padding: 5px;
      border-radius: 12px;
