    /* Multi-Select Dropdown Component (Locations, Target Roles, Core Skills) */
    .ms-dropdown-wrap {
      position: relative;
      width: 100%;
    }
    .ms-trigger {
      width: 100%;
      min-height: 34px;
      background: var(--bg-surface-2);
      border: 1px solid var(--border-color);
      border-radius: 8px;
      padding: 5px 8px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 6px;
      cursor: pointer;
      font-size: 11px;
      color: var(--text-main);
