    .ms-chips {
      display: flex;
      flex-wrap: wrap;
      gap: 4px;
      flex: 1;
    }
    .ms-chip {
      display: inline-flex;
      align-items: center;
      gap: 4px;
      padding: 3px 7px;
      border-radius: 6px;
      background: var(--bg-surface);
      color: var(--text-main);
      border: 1px solid var(--primary);
