    function isTextEntryElement(el) {
      if (!el || !el.tagName) return false;
      const tag = el.tagName.toUpperCase();
      if (tag === 'TEXTAREA') return !el.readOnly && !el.disabled;
      if (el.isContentEditable) return true;
      if (tag === 'INPUT') {
        const t = String(el.type || 'text').toLowerCase();
        const nonText = ['button', 'checkbox', 'radio', 'submit', 'reset', 'range', 'file', 'color', 'hidden', 'image'];
        return !nonText.includes(t) && !el.readOnly && !el.disabled;
      }
      return false;
    }

    (function setupKeyboardBottomBarAutoHide() {
      if (typeof document === 'undefined') return;
      let kbVisualOpen = false;
      let maxVvHeight = (typeof window !== 'undefined' && window.visualViewport) ? window.visualViewport.height : (typeof window !== 'undefined' ? window.innerHeight : 800);

      document.addEventListener('focusin', function(e) {
        if (isTextEntryElement(e.target)) {
          document.body.classList.add('kb-open');
          if (e.target && e.target.closest && e.target.closest('#cp-global-modals-root')) return;
          setTimeout(function() {
            try {
              if (e.target && typeof e.target.scrollIntoView === 'function') {
                e.target.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
              }
            } catch (_) {}
          }, 120);
        }
      }, true);

      document.addEventListener('focusout', function() {
        setTimeout(function() {
          if (!isTextEntryElement(document.activeElement) && !kbVisualOpen) {
            document.body.classList.remove('kb-open');
          }
        }, 100);
      }, true);

      if (typeof window !== 'undefined' && window.visualViewport) {
        window.visualViewport.addEventListener('resize', function() {
          const curH = window.visualViewport.height;
          if (curH > maxVvHeight) maxVvHeight = curH;
          if (maxVvHeight - curH > 110) {
            kbVisualOpen = true;
            document.body.classList.add('kb-open');
          } else {
            const wasOpen = kbVisualOpen;
            kbVisualOpen = false;
            if (wasOpen || !isTextEntryElement(document.activeElement)) {
              document.body.classList.remove('kb-open');
            }
          }
        });
      }
    })();

