    async function loadLiveState(showMsg) {
      try {
        const currentLoadedCount = (liveState && liveState._lazyInitialized && Array.isArray(liveState.jobs)) ? liveState.jobs.length : 0;
        const reqLimit = Math.max(lazyJobState.initialLimit || 15, currentLoadedCount, lazyJobState.visibleCount || 15);
        const r = await fetch('/webhook/job-dashboard-api', {
          method: 'POST',
          headers: {'Content-Type': 'application/json'},
          body: JSON.stringify({
            action: 'load_data',
            offset: 0,
            limit: reqLimit,
            companyFilter: jobFilterCompany,
            positionFilter: jobFilterPosition,
            statusFilter: jobFilterStatus,
            searchQuery: jobSearchQuery,
            sortBy: jobSortBy
          })
        });
        const freshState = await r.json();
        if (freshState && freshState.ok) {
          freshState._lazyInitialized = true;
          liveState = freshState;
          const jobs = liveState.jobs || [];
          normalizeJobArrayInPlace(jobs);
          const pag = liveState.lazyPagination || {};
          lazyJobState.totalAllJobs = Number(pag.totalAllJobs || (liveState.counts && liveState.counts.total) || jobs.length || 559);
          lazyJobState.totalMatchingJobs = Number(pag.totalMatchingJobs != null ? pag.totalMatchingJobs : lazyJobState.totalAllJobs);
          lazyJobState.hasMoreJobs = pag.hasMoreJobs != null ? Boolean(pag.hasMoreJobs) : (jobs.length < lazyJobState.totalMatchingJobs);
          lazyJobState.nextOffset = Number(pag.nextOffset != null ? pag.nextOffset : jobs.length);
          lazyJobState.visibleCount = Math.min(Math.max(15, lazyJobState.visibleCount || 15), Math.max(15, jobs.length));
          if (jobs.length && !jobs.some(j => String(j.sNo) === String(selectedJobSno))) {
            selectedJobSno = String(jobs[0].sNo || '1');
          }
          initPortalVaultState();
          buildMilestoneFeed();
          buildNotificationFeed();
          document.querySelectorAll('.bnav-item[data-bnav]').forEach(b => {
            b.classList.toggle('active', b.getAttribute('data-bnav') === currentPhoneTab);
          });
          document.querySelectorAll('.burger-item[data-ptab]').forEach(b => {
            b.classList.toggle('active', b.getAttribute('data-ptab') === currentPhoneTab);
          });
          updateCompanionMetrics();
          renderSimulator();
          renderHalfSlider();
          runClientQaChecks();
          if (window.cpRenderPatches && Array.isArray(liveState.uiPatches)) window.cpRenderPatches(liveState.uiPatches);
          if (showMsg) notifyToast('Real-time metrics & PostgreSQL RLS state synced!');
        }
      } catch (err) {
        console.error('loadLiveState error:', err);
      }
    }

    async function loadMoreJobsBatch(step, resetList) {
      const inc = Number(step) > 0 ? Number(step) : (lazyJobState.incrementStep || 5);
      if (lazyJobState.loadingMore && !resetList) return false;
      const currentJobs = (liveState && liveState.jobs) || [];
      if (!resetList && currentJobs.length >= lazyJobState.visibleCount + inc) {
        lazyJobState.visibleCount += inc;
        renderSimulator();
        return true;
      }
      if (!resetList && !lazyJobState.hasMoreJobs) {
        if (lazyJobState.visibleCount < currentJobs.length) {
          lazyJobState.visibleCount = currentJobs.length;
          renderSimulator();
        }
        return false;
      }
      lazyJobState.loadingMore = true;
      const btnEl = document.getElementById('lazy-load-more-btn');
      if (btnEl) {
        btnEl.disabled = true;
        btnEl.innerHTML = '⏳ Loading +' + inc + ' more jobs...';
      }
      try {
        const reqOffset = resetList ? 0 : currentJobs.length;
        const reqLimit = resetList ? (lazyJobState.initialLimit || 15) : inc;
        const r = await fetch('/webhook/job-dashboard-api', {
          method: 'POST',
          headers: {'Content-Type': 'application/json'},
          body: JSON.stringify({
            action: 'load_more_jobs',
            offset: reqOffset,
            limit: reqLimit,
            companyFilter: jobFilterCompany,
            positionFilter: jobFilterPosition,
            statusFilter: jobFilterStatus,
            searchQuery: jobSearchQuery,
            sortBy: jobSortBy
          })
        });
        const data = await r.json();
        if (data && data.ok && Array.isArray(data.jobs)) {
          normalizeJobArrayInPlace(data.jobs);
          if (!liveState) liveState = { ok: true, jobs: [] };
          if (data.jobFilterCatalog) liveState.jobFilterCatalog = data.jobFilterCatalog;
          if (resetList) {
            liveState.jobs = data.jobs;
            lazyJobState.visibleCount = Math.max(15, data.jobs.length);
          } else {
            const existingSnos = new Set((liveState.jobs || []).map(j => String(j.sNo)));
            for (const item of data.jobs) {
              if (!existingSnos.has(String(item.sNo))) {
                liveState.jobs.push(item);
                existingSnos.add(String(item.sNo));
              }
            }
            lazyJobState.visibleCount = (liveState.jobs || []).length;
          }
          const pag = data.lazyPagination || {};
          lazyJobState.totalAllJobs = Number(pag.totalAllJobs || (liveState.counts && liveState.counts.total) || lazyJobState.totalAllJobs || 559);
          lazyJobState.totalMatchingJobs = Number(pag.totalMatchingJobs != null ? pag.totalMatchingJobs : (data.totalMatchingJobs != null ? data.totalMatchingJobs : (liveState.jobs || []).length));
          lazyJobState.hasMoreJobs = pag.hasMoreJobs != null ? Boolean(pag.hasMoreJobs) : Boolean(data.hasMoreJobs);
          lazyJobState.nextOffset = (liveState.jobs || []).length;
        }
      } catch (err) {
        console.error('loadMoreJobsBatch error:', err);
      } finally {
        lazyJobState.loadingMore = false;
        renderSimulator();
        if (sliderState !== 'closed') renderHalfSlider();
      }
      return true;
    }

