        ptrBanner.style.cssText = 'position:fixed;top:8px;left:50%;transform:translate(-50%,-90px);z-index:99995;background:linear-gradient(135deg,#0f172a,#1e293b);border:1.5px solid #38bdf8;color:#f8fafc;padding:7px 16px;border-radius:999px;font-size:11px;font-weight:800;box-shadow:0 12px 30px rgba(0,0,0,0.75);display:flex;align-items:center;gap:7px;pointer-events:none;transition:transform 0.18s ease,opacity 0.18s ease,border-color 0.15s ease;opacity:0;white-space:nowrap;';
        ptrBanner.innerHTML = '<span id="cp-ptr-icon" style="font-size:13px;color:#38bdf8;display:inline-block;transition:transform 0.18s ease;">↓</span><span id="cp-ptr-text">Swipe down to refresh</span>';
        document.body.appendChild(ptrBanner);
      }

      let startY = 0;
      let startX = 0;
      let pulling = false;
      let readyToRefresh = false;
      const THRESHOLD = 68;

      document.addEventListener('touchstart', function(e) {
        if (!e.touches || e.touches.length !== 1) return;
        if (activePortalLoggedInView || (portalBrowserModalState && portalBrowserModalState.open) || (rulesModalState && rulesModalState.open) || portalResumePreviewOpen || portalDrivePickerOpen || (portalLongTextEditState && portalLongTextEditState.open)) {
          pulling = false;
          return;
        }
        const t = e.target;
        if (t && t.closest && t.closest('#cp-global-modals-root, .half-slider, #phone-half-slider, #burger-drawer, #swipe-card-container')) {
          pulling = false;
          return;
        }
        const bodyEl = document.getElementById('phone-body-content');
        const scrollTop = bodyEl ? bodyEl.scrollTop : (window.scrollY || document.documentElement.scrollTop || 0);
        if (scrollTop > 4) {
          pulling = false;
          return;
        }
        startY = e.touches[0].clientY;
        startX = e.touches[0].clientX;
        pulling = true;
        readyToRefresh = false;
      }, { passive: true });

      document.addEventListener('touchmove', function(e) {
        if (!pulling || !e.touches || e.touches.length !== 1) return;
        const bodyEl = document.getElementById('phone-body-content');
        const scrollTop = bodyEl ? bodyEl.scrollTop : (window.scrollY || document.documentElement.scrollTop || 0);
        if (scrollTop > 4) {
          pulling = false;
          ptrBanner.style.opacity = '0';
          ptrBanner.style.transform = 'translate(-50%,-90px)';
          return;
        }
        const dy = e.touches[0].clientY - startY;
        const dx = e.touches[0].clientX - startX;
        if (dy < -6 || (Math.abs(dx) > 18 && Math.abs(dx) > Math.abs(dy))) {
          pulling = false;
          ptrBanner.style.opacity = '0';
          ptrBanner.style.transform = 'translate(-50%,-90px)';
          return;
        }
        if (dy > 14) {
          const offset = Math.min(48, Math.round((dy - 14) * 0.48));
          ptrBanner.style.transition = 'none';
          ptrBanner.style.opacity = String(Math.min(1, (dy - 10) / 45));
          ptrBanner.style.transform = 'translate(-50%,' + offset + 'px)';
          const iconEl = document.getElementById('cp-ptr-icon');
          const txtEl = document.getElementById('cp-ptr-text');
          if (dy >= THRESHOLD) {
            readyToRefresh = true;
            ptrBanner.style.borderColor = '#10b981';
            if (iconEl) { iconEl.style.color = '#34d399'; iconEl.style.transform = 'rotate(180deg)'; }
            if (txtEl) txtEl.textContent = 'Release to refresh page';
          } else {
            readyToRefresh = false;
            ptrBanner.style.borderColor = '#38bdf8';
            if (iconEl) { iconEl.style.color = '#38bdf8'; iconEl.style.transform = 'rotate(0deg)'; }
            if (txtEl) txtEl.textContent = 'Swipe down to refresh';
          }
        }
      }, { passive: true });

      function endPull() {
        if (!pulling) return;
        pulling = false;
        ptrBanner.style.transition = 'transform 0.2s ease, opacity 0.2s ease';
        if (readyToRefresh) {
          readyToRefresh = false;
          ptrBanner.style.opacity = '1';
          ptrBanner.style.transform = 'translate(-50%, 16px)';
          ptrBanner.style.borderColor = '#10b981';
          const iconEl = document.getElementById('cp-ptr-icon');
          const txtEl = document.getElementById('cp-ptr-text');
          if (iconEl) { iconEl.textContent = '⟳'; iconEl.style.color = '#34d399'; }
          if (txtEl) txtEl.textContent = 'Refreshing page...';
          setTimeout(function() {
            triggerPullToRefreshReload();
          }, 120);
        } else {
          ptrBanner.style.opacity = '0';
          ptrBanner.style.transform = 'translate(-50%,-90px)';
        }
      }

      document.addEventListener('touchend', endPull, { passive: true });
      document.addEventListener('touchcancel', endPull, { passive: true });
    }

