        const boostedSum = `<p><strong>Senior Data &amp; Business Analyst</strong> tailored for <strong>${escH(j.company)}</strong> (${escH(j.role || j.title)}) with end-to-end expertise in <strong>SQL, Python, Tableau, ${escH(addedKeywords)}</strong>, automated KPI governance, and executive decision pipelines.</p>`;
