      }
      if (mode === 'both' || mode === 'cl') {
        j._boostedCl = true;
        if (mode === 'both') j._boosted = true;
        j.clSections.para2_stewardship_html = `<p>Throughout my career across high-volume operational and business intelligence environments, I have focused on turning complex, fragmented datasets into clear decision frameworks using <strong>SQL, Python, Tableau, and ${escH(addedKeywords)}</strong>. Whether automating recurring ETL workflows or establishing governed KPI definitions across teams, I prioritize data accuracy and measurable commercial impact for <strong>${escH(j.company)}</strong>.</p>`;
        j.clHtml = getFullCoverLetterHtml(j);
