    function parseLiInsiderMeta(item) {
      if (!item) return { name: 'LinkedIn Member', position: 'Analytics & Strategy', company: 'Company', profileUrl: 'https://www.linkedin.com', postUrl: 'https://www.linkedin.com' };
      const rawPerson = String(item.insider_name || item.targetPerson || 'LinkedIn Member').trim();
      const rawComp = String(item.company_name || item.company || 'Company').trim();
      let name = rawPerson;
      let position = '';
      const parenMatch = rawPerson.match(/^([^(]+)\(([^)]+)\)/);
      if (parenMatch) {
        name = parenMatch[1].trim();
        let inside = parenMatch[2].trim();
        // Strip trailing company mentions like ", Swiggy" or "@ McKinsey"
        const parts = inside.split(',');
        if (parts.length > 1) {
          const lastPart = parts[parts.length - 1].trim().toLowerCase();
          const compLower = rawComp.toLowerCase();
          if (compLower.includes(lastPart) || lastPart.startsWith('ex-') || lastPart.includes('amex') || lastPart.includes('bain') || lastPart.includes('citi')) {
            position = parts.slice(0, -1).join(',').trim();
          } else {
            position = inside;
          }
        } else {
          position = inside;
        }
        position = position.replace(/\s*@\s*[^,]+$/i, '').trim();
      }
      if (!position) {
        const fallbackPositions = {
          'LI-12': 'Senior Analyst — Market & Attribution Analytics',
          'LI-9': 'Product & Analytics Leader',
          'LI-6': 'Data & Growth Analytics Specialist',
          'LI-3': 'Manager, Data Science',
          'LI-1': 'Senior Analytics Consultant'
        };
        const id = String(item.activity_id || item.id || '');
        position = fallbackPositions[id] || item.position || item.role_title || 'Data & Analytics Professional';
      }
      const profileUrl = (item.target_profile_url && item.target_profile_url.startsWith('http'))
        ? item.target_profile_url
        : ((item.profileUrl && item.profileUrl.startsWith('http'))
            ? item.profileUrl
            : ((item.linkedin_url && item.linkedin_url.startsWith('http')) ? item.linkedin_url : 'https://www.linkedin.com'));
      const postUrl = (item.linkedin_url && item.linkedin_url.startsWith('http'))
        ? item.linkedin_url
        : ((item.postUrl && item.postUrl.startsWith('http')) ? item.postUrl : profileUrl);
      return { name, position, company: rawComp, profileUrl, postUrl };
    }

