    function enforceMobileViewportScale() {
      document.documentElement.style.zoom = '';
    }

    function applyMobileAccessibilityPolish() {
      const appNameHdr = document.getElementById('phone-app-name');
      if (appNameHdr && appNameHdr.textContent.trim() !== 'CareerPulse') {
        appNameHdr.textContent = 'CareerPulse';
      }
      const frame = document.getElementById('phone-frame-el');
      if (!frame) return;
      const isMobileOnly = document.body.classList.contains('mobile-only-mode');
      enforceMobileViewportScale();

      // 1. Ensure every input, select, and textarea has an accessible label (aria-label + title)
      frame.querySelectorAll('input, select, textarea').forEach((el, idx) => {
        if (!el.getAttribute('aria-label')) {
          const ph = el.getAttribute('placeholder') || el.getAttribute('title') || '';
          const firstOpt = el.tagName === 'SELECT' && el.options && el.options[0] ? el.options[0].text : '';
          const fallback = ph || firstOpt || el.id || ('Mobile Form Control ' + (idx + 1));
          el.setAttribute('aria-label', fallback);
          if (!el.getAttribute('title')) el.setAttribute('title', fallback);
        }
        if (el.type === 'checkbox') {
          el.style.minWidth = '28px';
          el.style.minHeight = '28px';
          el.style.width = '28px';
          el.style.height = '28px';
          el.style.cursor = 'pointer';
        }
      });
      // 2. Enforce comfortable touch target minimum on all buttons and interactive elements inside phone frame
      const minTap = isMobileOnly ? '38px' : '28px';
      frame.querySelectorAll('button, a, [onclick], input[type="checkbox"], select').forEach(btn => {
        if (btn.classList && (btn.classList.contains('left-edge-pull-tab') || btn.classList.contains('notif-draft-more-inline') || btn.classList.contains('dash-kpi-compact') || btn.classList.contains('dash-todo-btn') || btn.classList.contains('dash-todo-tab-btn') || btn.classList.contains('dash-todo-more-link'))) return;
        btn.style.minHeight = minTap;
        btn.style.minWidth = minTap;
        if (btn.tagName === 'SPAN') {
          btn.style.display = 'inline-flex';
          btn.style.alignItems = 'center';
          btn.style.justifyContent = 'center';
        }
      });
      // 3. Upgrade inline font sizes & cramped multi-column grids when in mobile-only-mode
      frame.querySelectorAll('*').forEach(el => {
        if (el.closest && el.closest('.dash-kpi-4row')) return;
        const inlineFs = el.style && el.style.fontSize;
        if (inlineFs && /^[0-9.]+px$/i.test(inlineFs)) {
          const origNum = parseFloat(el.getAttribute('data-orig-fs') || inlineFs);
          if (!el.getAttribute('data-orig-fs')) {
            el.setAttribute('data-orig-fs', String(origNum));
          }
          if (isMobileOnly) {
            if (origNum <= 9.5) {
              el.style.fontSize = '12px';
            } else if (origNum <= 10.8) {
              el.style.fontSize = '13px';
            } else if (origNum <= 12.2) {
              el.style.fontSize = '14px';
            } else if (origNum <= 14.5) {
              el.style.fontSize = '15.5px';
            } else if (origNum <= 19) {
              el.style.fontSize = (origNum + 2.5) + 'px';
            }
          } else if (origNum < 10) {
            el.style.fontSize = '10px';
          }
        }
        if (isMobileOnly && el.style && el.style.gridTemplateColumns) {
          const gtc = el.style.gridTemplateColumns.replace(/\s+/g, '');
          if (gtc.includes('repeat(4,1fr)')) {
            el.style.gridTemplateColumns = 'repeat(2, 1fr)';
            el.style.gap = '8px';
          } else if (gtc === '1fr1fr1.1fr') {
            el.style.gridTemplateColumns = '1fr 1fr';
            el.style.gap = '8px';
          }
        }
      });
    }

    function renderSimulator() {
      if (!liveState) return;
      if (typeof isTextEntryElement === 'function' && !isTextEntryElement(document.activeElement)) {
        document.body.classList.remove('kb-open');
      }
      const titleEl = document.getElementById('phone-active-title');
      if (titleEl && typeof PHONE_TAB_TITLES === 'object') {
        titleEl.textContent = PHONE_TAB_TITLES[currentPhoneTab] || 'Dashboard';
      }
      const backBtn = document.getElementById('phone-back-btn');
      if (backBtn) {
        backBtn.style.display = (currentPhoneTab === 'funnel') ? 'none' : 'inline-flex';
      }
      document.querySelectorAll('.bnav-item[data-bnav]').forEach(b => {
        b.classList.toggle('active', b.getAttribute('data-bnav') === currentPhoneTab);
      });
      document.querySelectorAll('.burger-item[data-ptab]').forEach(b => {
        b.classList.toggle('active', b.getAttribute('data-ptab') === currentPhoneTab);
      });
      const isSliderAllowed = isSliderCurrentlyAllowed();
      if (!isSliderAllowed) {
        sliderState = 'closed';
      }
      const body = document.getElementById('phone-body-content');
      const sliderEl = document.getElementById('phone-half-slider');
      if (sliderEl) {
        sliderEl.className = 'half-slider state-' + (isSliderAllowed ? sliderState : 'closed');
        sliderEl.style.display = isSliderAllowed ? 'flex' : 'none';
      }
      const bd = document.getElementById('phone-slider-backdrop');
      if (bd) bd.classList.toggle('open', isSliderAllowed && sliderState !== 'closed');
      const dashTopKpi = document.getElementById('dash-top-kpi-bar');
      if (dashTopKpi) dashTopKpi.style.display = (isSliderAllowed && sliderState !== 'closed') ? 'none' : 'block';
      const pullTab = document.getElementById('left-edge-pull-tab');
      syncPullTabDomState(pullTab);

      if (currentPhoneTab === 'funnel') {
        renderMobileDashboardTab(body);
      } else if (currentPhoneTab === 'jobs') {
        renderMobileJobsTab(body);
      } else if (currentPhoneTab === 'a4') {
        renderMobileA4ResumeTab(body);
      } else if (currentPhoneTab === 'portals') {
        renderMobilePortalsTab(body);
      } else if (currentPhoneTab === 'linkedin') {
        renderMobileLinkedInTab(body);
      } else if (currentPhoneTab === 'notifications') {
        renderMobileNotificationsTab(body);
      } else if (currentPhoneTab === 'profile') {
        renderMobileProfileTab(body);
      } else if (currentPhoneTab === 'settings') {
        renderMobileSettingsTab(body);
      } else if (currentPhoneTab === 'gdpr') {
        renderMobileGdprTab(body);
      } else if (currentPhoneTab === 'todos') {
        renderMobileTodosTab(body);
      } else if (currentPhoneTab === 'theme') {
        renderMobileThemeTab(body);
      }
      applyMobileAccessibilityPolish();
    }


