    function applyAutoReplyRulesToNotifications() {
      if (!Array.isArray(notificationState)) return;
      notificationState.forEach(n => {
        if (n.status === 'Rejected' || n.status === 'Sent') return;
        const shouldAuto = (n.category === 'emails' && appAutomationSettings.autoReplyEmails)
          || (n.category === 'calls' && appAutomationSettings.autoReplyMissedCalls)
          || (n.category === 'messages' && appAutomationSettings.autoReplyAppMessages);
        if (shouldAuto) {
          n.status = 'Auto-Replied';
          n.auto_replied = true;
        } else if (n.status === 'Auto-Replied') {
          n.status = 'Pending';
          n.auto_replied = false;
        }
      });
    }

    function updateNotificationBadge() {
      const badgeEl = document.getElementById('bnav-notif-badge');
      if (!badgeEl) return;
      const pendingCount = (notificationState || []).filter(n => !/sent|auto-replied|reject|ignore/i.test(String(n.status || ''))).length;
      const displayCount = pendingCount > 0 ? pendingCount : (notificationState || []).length;
      badgeEl.textContent = String(displayCount);
      badgeEl.style.background = pendingCount > 0 ? '#ef4444' : 'var(--primary)';
    }

    // Bridge for Android Native NotificationListenerService / Call Log / SMS Forwarder
    window.ingestPhoneNotification = function(payload) {
      if (!payload || typeof payload !== 'object') return;
      buildNotificationFeed();
      const cat = String(payload.category || (payload.isCall || payload.isSms ? 'calls' : (payload.isEmail ? 'emails' : 'messages'))).toLowerCase();
      const autoOn = (cat === 'emails' && appAutomationSettings.autoReplyEmails)
        || (cat === 'calls' && appAutomationSettings.autoReplyMissedCalls)
        || (cat === 'messages' && appAutomationSettings.autoReplyAppMessages);
      const newItem = {
        id: String(payload.id || ('NOTIF-LIVE-' + Date.now())),
        category: cat,
        call_type: payload.isCall ? 'missed_call' : 'sms_only',
        portal_or_app: String(payload.portal_or_app || payload.appName || 'Phone Notification'),
        channel_badge: String(payload.channel_badge || 'Alert'),
        sender_name: String(payload.sender_name || payload.title || 'Recruiter'),
        profile_url: String(payload.profile_url || 'https://www.linkedin.com'),
        phone_number: String(payload.phone_number || '+919820471290'),
        company_name: String(payload.company_name || 'Hiring Company'),
        role_title: String(payload.role_title || 'Analytics Role'),
        date_str: String(payload.date_str || 'Just now'),
        subject: cat === 'calls' ? '' : String(payload.subject || payload.one_liner || payload.summary || 'New Incoming Notification'),
        last_reply: String(payload.last_reply || payload.text || ''),
        link_url: String(payload.link_url || payload.profile_url || '#'),
        incoming_text: String(payload.incoming_text || payload.text || ''),
        chat_history: Array.isArray(payload.chat_history) ? payload.chat_history : [
          { sender: 'them', time: 'Just now', text: String(payload.incoming_text || payload.text || '') }
        ],
        draft: String(payload.draft || 'Hi, thank you for reaching out! I am available for a quick discussion today and have attached my updated CV for your review.'),
        status: autoOn ? 'Auto-Replied' : 'Pending',
        auto_replied: !!autoOn,
        rule_learnt: false
      };
      notificationState.unshift(newItem);
      updateNotificationBadge();
      if (currentPhoneTab === 'notifications') {
        renderSimulator();
      }
      notifyToast(autoOn ? `⚡ Auto-Replied to ${newItem.sender_name} (${newItem.company_name})!` : `🔔 New alert from ${newItem.sender_name} (${newItem.company_name})`);
    };

    function getSelectedNotification() {
      if (activeNotifId) {
        const found = notificationState.find(x => String(x.id) === String(activeNotifId));
        if (found) return found;
      }
      return notificationState[0] || {};
    }

    function selectNotificationCard(nId) {
      const id = String(nId);
      if (String(activeNotifId || '') === id) {
        activeNotifId = null;
        sliderState = 'closed';
      } else {
        activeNotifId = id;
      }
      renderSimulator();
      renderHalfSlider();
