    // Slider AI Rewrite Mode Switcher: 'edit' fills textbox with draft answer; 'rewrite' takes feedback
    function switchNotifAiMode(mode, nId) {
      notifAiMode = (mode === 'edit') ? 'edit' : 'rewrite';
