    async function submitSliderNotifAiRewrite(nId, saveRule) {
      const n = getSelectedNotification();
      if (!n) return;
      const boxVal = document.getElementById('sl-notif-main-box')?.value || notifFeedbackMap[nId] || '';
      const fb = boxVal.trim() || 'Rewrite concisely and confirm availability this week';
      const first = String(n.sender_name || 'there').split(' ')[0];
      const comp = String(n.company_name || 'your team').split('/')[0].trim();
      const role = String(n.role_title || 'the role').trim();

      let rewritten = '';
      if (/15-minute|availability|today|scratch/i.test(fb)) {
        rewritten = `Hi ${first}, thank you for reaching out regarding the ${role} position at ${comp}! I am available today between 3:00 PM and 6:00 PM CET (or tomorrow morning) for a 15-minute call. Looking forward to speaking with you.`;
      } else if (/concise|20 words|short/i.test(fb)) {
        rewritten = `Hi ${first}, thank you for the note! I am available today after 2:00 PM CET to discuss the ${role} role at ${comp}.`;
      } else if (/CV|SQL|Python|experience/i.test(fb)) {
        rewritten = `Hi ${first}, sharing my updated 1-page Master CV highlighting 8+ years in SQL, Python, experimentation, and Executive BI. Excited to discuss the ${role} opportunity at ${comp}!`;
      } else if (/JD|compensation|band/i.test(fb)) {
        rewritten = `Hi ${first}, thank you for connecting regarding the ${role} opening at ${comp}. Could you share the detailed job description and compensation band ahead of our call?`;
      } else {
        rewritten = `Hi ${first}, thank you for your message regarding the ${role} role at ${comp}. ${fb.replace(/^(make it|say|write|rewrite)\s+/i, '')}. Best regards, Sumanto.`;
      }

      n.draft = rewritten;
      if (saveRule) {
        n.rule_learnt = true;
      }
      notifyToast(saveRule ? `✨ Applied feedback & learned rule for ${n.sender_name}!` : `✨ Rewrote draft for ${n.sender_name}!`);
      renderSimulator();
      renderHalfSlider();
      if (saveRule) {
        const notifSecName = n.category === 'calls' ? 'Message Reply' : (n.category === 'messages' ? 'Chat Reply' : 'Email Reply');
        try {
          const rResp = await fetch('/webhook/job-dashboard-api', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({ action: 'rule_action', subAction: 'add', sectionName: notifSecName, ruleInstruction: fb })
          });
          if (rResp.ok) {
            const rData = await rResp.json();
            if (rData && Array.isArray(rData.rules) && liveState) {
              liveState.rules = rData.rules;
              renderHalfSlider();
            }
          }
        } catch (e) {}
      }
    }

    async function handleNotificationAction(nId, act) {
      const n = notificationState.find(x => String(x.id) === String(nId));
      if (!n) return;
      if (act === 'send') {
        n.status = 'Sent';
        if (n.category === 'messages' && Array.isArray(n.chat_history)) {
          n.chat_history.push({ sender: 'me', time: 'Just now', text: n.draft });
        }
        const actionLabel = n.category === 'calls'
          ? '📲 Sent follow-up text'
          : (n.category === 'emails' ? '📧 Sent email reply' : '💬 Sent message reply');
        notifyToast(`${actionLabel} to ${n.sender_name} (${n.company_name})!`);
      } else {
        n.status = 'Rejected';
        notifyToast(`🚫 Ignored notification from ${n.sender_name}`);
      }
      updateNotificationBadge();
      renderSimulator();
      renderHalfSlider();
    }

