            : 'border-width: 1.5px !important;';

          const isCallsTab = item.category === 'calls';
          const isMessagesTab = item.category === 'messages';
          const isMissedCall = isCallsTab && item.call_type === 'missed_call';
          const nameHref = isMessagesTab ? (item.profile_url || 'https://www.linkedin.com') : (item.link_url || '#');

          const primaryBtnLabel = isSent
            ? '<i class="bi bi-check2-circle"></i> Replied'
            : (isCallsTab
                ? '<i class="bi bi-chat-dots-fill"></i> Send Text'
                : '<i class="bi bi-reply-fill"></i> Send Reply');

          // Top-right phone call button on Calls & SMS cards (red missed-call sign vs normal call sign)
          const topRightCallBtn = isCallsTab ? `
            <a href="tel:${escH(item.phone_number || '')}" onclick="event.stopPropagation();" title="${isMissedCall ? 'Missed Call — Tap to Call Back' : 'Tap to Call'}" style="width:32px;height:32px;border-radius:9px;display:inline-flex;align-items:center;justify-content:center;text-decoration:none;flex-shrink:0;border:1.5px solid ${isMissedCall ? '#ef4444' : 'var(--primary)'};background:${isMissedCall ? 'rgba(239, 68, 68, 0.18)' : 'var(--primary-soft)'};color:${isMissedCall ? '#ef4444' : 'var(--accent)'};">
