                  <!-- 1. Name -->
                  <div style="font-size:11.5px;font-weight:800;color:var(--text-main);line-height:1.25;">
                    <a href="${escH(nameHref)}" target="_blank" rel="noopener" onclick="event.stopPropagation();" style="color:var(--text-main);text-decoration:none;">
