                  <!-- 2. Company -->
                  <div style="font-size:10px;color:var(--text-secondary);font-weight:700;margin-top:2px;line-height:1.25;">
                    ${escH(item.company_name)}
                  </div>
                  <!-- 3. Position -->
                  <div style="font-size:9.8px;color:var(--accent);font-weight:700;margin-top:2px;line-height:1.25;">
                    ${escH(item.role_title)}
                  </div>
                </div>
                ${topRightCallBtn}
              </div>
              <!-- 4. Date (+ Rule learnt / Auto-Replied) -->
              <div style="display:flex;justify-content:space-between;align-items:center;margin-top:4px;margin-bottom:4px;line-height:1.2;">
                <span style="font-size:9.5px;color:var(--text-muted);font-weight:700;">${escH(item.date_str)}</span>
                <div style="display:flex;align-items:center;gap:6px;">
                  ${item.auto_replied ? `<span style="font-size:9px;color:#10b981;font-weight:800;">Auto-Replied ✓</span>` : ''}
                  ${item.rule_learnt ? `<span style="font-size:9.5px;color:var(--accent);font-weight:800;">Rule learnt</span>` : ''}
                </div>
              </div>
              <!-- 5. Subject (Emails) / Last Reply (Messages) / None (Calls & SMS) -->
              ${lineFiveHtml}
              <!-- 6. Draft answer (2 lines with "more..." at the end of line 2) -->
              <div style="background:var(--bg-surface-2);border:1px solid var(--border-color);border-radius:8px;padding:7px 9px;margin:0 0 8px 0;">
                <div id="notif-draft-preview-${escH(id)}" class="notif-draft-clamp" style="font-size:10.2px;color:var(--text-secondary);font-weight:600;">
                  <span id="notif-draft-text-${escH(id)}">${escH(item.draft)}</span>
                  <a href="javascript:void(0)" class="notif-draft-more-inline" onclick="event.stopPropagation();openNotifDraftModal('${escH(id)}')" style="font-size:10px;">more...</a>
                </div>
              </div>
              <!-- 7. Buttons -->
              <div style="display:flex;gap:6px;" onclick="event.stopPropagation();">
                <button type="button" class="m-btn m-btn-success" style="flex:1;" onclick="event.stopPropagation();handleNotificationAction('${escH(id)}', 'send')">
