    function handleDashTodoAction(type, id, act, ev) {
      if (ev) ev.stopPropagation();
      initDashboardTodosState();
      const list = type === 'user' ? dashTodosState.user : dashTodosState.ai;
      const item = list.find(x => x.id === id);
      if (!item) return;

      if (type === 'user') {
        if (act === 'done') {
          item.done = !item.done;
          notifyToast(item.done ? `✅ Marked Done: ${item.title}` : `↩️ Reopened: ${item.title}`);
        } else if (act === 'skip') {
          item.skipped = true;
          notifyToast(`⏭️ Skipped: ${item.title}`);
        }
      } else {
        if (act === 'approve') {
          item.approved = !item.approved;
          if (item.approved) item.paused = false;
          notifyToast(item.approved ? `✅ Approved AI To-Do: ${item.title}` : `↩️ Unapproved: ${item.title}`);
        } else if (act === 'pause') {
          item.paused = !item.paused;
          notifyToast(item.paused ? `⏸️ Paused AI To-Do: ${item.title}` : `▶️ Resumed AI To-Do: ${item.title}`);
        } else if (act === 'skip') {
          item.skipped = true;
          notifyToast(`⏭️ Skipped AI To-Do: ${item.title}`);
        }
      }
      renderSimulator();
      if (sliderState !== 'closed') renderHalfSlider();
    }

