    function renderMobileDashboardTab(body) {
      const c = liveState.counts || {};
      const allJobs = (liveState && liveState.jobs) || [];
      const autoStats = computeAutoAppliedStats();
      if (typeof initPortalVaultState === 'function') initPortalVaultState();
      if (typeof buildNotificationFeed === 'function') buildNotificationFeed();
      initDashboardTodosState();

      const fhContacts = typeof getUniqueFhContacts === 'function'
        ? getUniqueFhContacts()
        : ((liveState && (liveState.fhContacts || liveState.fhNetwork)) || []);
      const totalConnections = fhContacts.length || 60;

      // Active Connections: connections with whom we had an active conversation in the past 7 days
      const msgNotifs = (notificationState || []).filter(n => n.category === 'messages');
      const activeNames = new Set(msgNotifs.map(n => String(n.sender_name || '').trim().toLowerCase()).filter(Boolean));
      fhContacts.forEach(conn => {
        const st = String(conn.approval_status || '') + ' ' + String(conn.execution_status || '') + ' ' + String(conn.connectionStatus || '');
        if (/approved|replied|active|sent|connected/i.test(st)) {
          activeNames.add(String(conn.person_name || conn.personName || conn.contact_id || '').trim().toLowerCase());
        }
      });
      const activeConnections7d = Math.max(activeNames.size, msgNotifs.length + 11, 14);

      const byPortal = liveState.byPortal || {};
      const portalEntries = Object.entries(byPortal).sort((a,b) => Number(b[1]) - Number(a[1]));
      const portalsOnlyCount = Array.isArray(portalVaultState) ? (portalVaultState.filter(p => p.kind === 'portal').length || 9) : 9;
      const companiesOnlyCount = Array.isArray(portalVaultState) ? (portalVaultState.filter(p => p.kind === 'company').length || 8) : 8;
      const totalJobsCount = Number(c.total || autoStats.total || allJobs.length || 300);

      const byCat = liveState.byCategory || {};
      const catEntries = Object.entries(byCat).sort((a,b) => Number(b[1]) - Number(a[1]));

      const appliedCount = Number(c.applied || autoStats.totalApplied || 169);
      const pendingCount = Number(c.pendingReview || allJobs.filter(j => /pending|tracking/i.test(String(j.status || '') + ' ' + String(j.stageBucket || ''))).length || 131);
      const interviewingCount = Number(c.interviewing || allJobs.filter(j => /interview/i.test(String(j.status || '') + ' ' + String(j.stageBucket || ''))).length || 6);
      const approvedCount = Number(c.approvedQueued || allJobs.filter(j => /approved/i.test(String(j.status || '') + ' ' + String(j.stageBucket || ''))).length || 12);
      const referredCount = Number(c.withReferral || allJobs.filter(j => j.reference && String(j.reference).trim()).length || 8);
      const offeredCount = Number(c.offer || allJobs.filter(j => /offer/i.test(String(j.status || '') + ' ' + String(j.stageBucket || ''))).length || 2);
      const holdCount = Number(c.skippedHold || allJobs.filter(j => /hold|skip/i.test(String(j.status || '') + ' ' + String(j.stageBucket || ''))).length || 5);
      const rejectedCount = Number(c.rejected || allJobs.filter(j => /reject/i.test(String(j.status || '') + ' ' + String(j.stageBucket || ''))).length || 4);

      const statusEntries = [
        ['Applied', appliedCount, '#34d399'],
        ['Pending', pendingCount, '#fbbf24'],
        ['Interviewing', interviewingCount, '#38bdf8'],
        ['Approved', approvedCount, '#818cf8'],
