            <div class="m-card dash-kpi-compact" onclick="setPhoneTab('jobs')" style="margin-bottom:0;padding:6px 7px !important;cursor:pointer;border-color:rgba(56,189,248,0.35);">
              <div style="font-size:13.5px;font-weight:900;color:var(--accent);line-height:1.15;text-align:left;white-space:nowrap;">${appliedCount} <span style="font-size:11px;color:var(--text-muted);font-weight:700;">/ ${totalJobsCount}</span></div>
