            </div>
            <div class="m-card dash-kpi-compact" onclick="setPhoneTab('portals')" style="margin-bottom:0;padding:6px 7px !important;cursor:pointer;border-color:rgba(129,140,248,0.35);">
              <div style="font-size:13.5px;font-weight:900;color:var(--primary);line-height:1.15;text-align:left;white-space:nowrap;">${portalsOnlyCount} <span style="font-size:11px;color:var(--text-muted);font-weight:700;">/ ${companiesOnlyCount}</span></div>
              <div style="font-size:8.5px;color:var(--text-muted);font-weight:700;margin-top:2px;text-align:left;white-space:nowrap;">Portals / Companies</div>
            </div>
            <div class="m-card dash-kpi-compact" onclick="liSubTab='connections';setPhoneTab('linkedin');" style="margin-bottom:0;padding:6px 7px !important;cursor:pointer;border-color:rgba(56,189,248,0.35);">
              <div style="display:flex;justify-content:space-between;align-items:center;gap:4px;">
                <span style="font-size:13.5px;font-weight:900;color:var(--accent);line-height:1.15;text-align:left;">${totalConnections}</span>
                <i class="bi bi-linkedin" style="font-size:13px;color:#0a66c2;line-height:1;"></i>
              </div>
              <div style="font-size:8.5px;color:var(--text-muted);font-weight:700;margin-top:2px;text-align:left;white-space:nowrap;">Connections</div>
            </div>
          </div>
        </div>

        <!-- To-Dos Card (Just above Job Stats): Two tabs (User and AI), 3 items shown, "More" opens full list in Slider -->
        <div class="m-card" style="padding:8px 9px;margin-bottom:8px;">
          <div style="display:flex;justify-content:space-between;align-items:center;gap:6px;margin-bottom:7px;">
            <div style="display:inline-flex;background:var(--bg-surface-2);border:1px solid var(--border-color);border-radius:7px;padding:2px;gap:2px;">
              <button type="button" class="dash-todo-tab-btn" style="border:none;border-radius:5px;padding:4px 12px !important;font-size:9.8px !important;font-weight:800;cursor:pointer;background:${dashTodoTab === 'user' ? 'var(--primary)' : 'transparent'};color:${dashTodoTab === 'user' ? '#ffffff' : 'var(--text-muted)'};" onclick="dashTodoTab='user';renderSimulator();if(sliderState!=='closed')renderHalfSlider();">
                User (${userTodos.length})
              </button>
              <button type="button" class="dash-todo-tab-btn" style="border:none;border-radius:5px;padding:4px 12px !important;font-size:9.8px !important;font-weight:800;cursor:pointer;background:${dashTodoTab === 'ai' ? 'var(--primary)' : 'transparent'};color:${dashTodoTab === 'ai' ? '#ffffff' : 'var(--text-muted)'};" onclick="dashTodoTab='ai';renderSimulator();if(sliderState!=='closed')renderHalfSlider();">
                AI (${aiTodos.length})
              </button>
            </div>
            <a href="javascript:void(0)" class="dash-todo-more-link" onclick="openDashTodosSlider('${dashTodoTab}', event)" style="font-size:9.8px !important;font-weight:800;color:var(--accent);text-decoration:underline;cursor:pointer;">
              More
            </a>
          </div>
          <div style="display:flex;flex-direction:column;gap:6px;">
            ${topThreeTodos.map(item => renderDashTodoItemHtml(item, dashTodoTab)).join('')}
          </div>
        </div>

        <!-- Job Stats Card (Clicking "Job Stats" redirects to Jobs tab; Dropdown for By Portals, By Roles, By Status) -->
        <div class="m-card" style="padding:8px 9px;">
          <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:8px;">
            <div onclick="setPhoneTab('jobs')" style="font-size:11px;font-weight:800;color:var(--text-primary);cursor:pointer;">
              Job Stats
            </div>
            <select class="m-select" style="width:auto;min-width:124px;padding:3px 7px;font-size:10px;font-weight:800;" onclick="event.stopPropagation();" onchange="dashBreakdownMode=this.value;renderSimulator();">
              <option value="portal" ${dashBreakdownMode === 'portal' ? 'selected' : ''}>By Portals</option>
              <option value="category" ${dashBreakdownMode === 'category' ? 'selected' : ''}>By Roles</option>
              <option value="status" ${dashBreakdownMode === 'status' ? 'selected' : ''}>By Status</option>
            </select>
          </div>
          ${dashBreakdownMode === 'portal' ? portalEntries.slice(0, 8).map(([k, v]) => {
            const pct = Math.max(8, Math.round((Number(v) / (Number(portalEntries[0]?.[1]) || 80)) * 100));
            return `<div style="margin-bottom:6px;">
              <div style="display:flex;justify-content:space-between;font-size:10px;margin-bottom:2px;">
                <span style="font-weight:600;">${escH(k)}</span>
                <span style="color:var(--accent);font-weight:800;">${v}</span>
              </div>
              <div style="height:5px;background:var(--bg-surface-2);border-radius:99px;overflow:hidden;">
                <div style="height:100%;width:${pct}%;background:linear-gradient(90deg,var(--primary),var(--success));"></div>
              </div>
            </div>`;
          }).join('') : dashBreakdownMode === 'category' ? catEntries.slice(0, 8).map(([k, v]) => {
            const pct = Math.max(8, Math.round((Number(v) / (Number(catEntries[0]?.[1]) || 77)) * 100));
            const label = k.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase());
            return `<div style="margin-bottom:6px;">
              <div style="display:flex;justify-content:space-between;font-size:10px;margin-bottom:2px;">
                <span style="font-weight:600;">${escH(label)}</span>
                <span style="color:var(--success);font-weight:800;">${v}</span>
              </div>
              <div style="height:5px;background:var(--bg-surface-2);border-radius:99px;overflow:hidden;">
                <div style="height:100%;width:${pct}%;background:linear-gradient(90deg,var(--accent),var(--primary));"></div>
              </div>
            </div>`;
          }).join('') : statusEntries.map(([label, val, col]) => {
            const maxStatusVal = Math.max(1, Number(statusEntries[0]?.[1]) || totalJobsCount);
            const pct = Math.max(6, Math.round((Number(val) / maxStatusVal) * 100));
            const statusMap = {
              'Applied': 'Applied',
              'Pending': 'Pending Review',
              'Interviewing': 'Interviewing',
              'Approved': 'Approved',
              'Referred': 'Referred',
              'On Hold': 'Hold / Skip',
              'Rejected': 'Rejected',
              'Offered': 'Offer Received'
            };
            const targetFilter = statusMap[label] || 'ALL';
            return `<div onclick="jobFilterStatus='${escH(targetFilter)}';swipeCursor=0;lazyJobsLimit=15;setPhoneTab('jobs');" style="margin-bottom:6px;cursor:pointer;padding:3px 5px;border-radius:6px;transition:background 0.15s;" title="Tap to view all ${escH(label)} jobs">
              <div style="display:flex;justify-content:space-between;font-size:10px;margin-bottom:2px;">
                <span style="font-weight:700;display:inline-flex;align-items:center;gap:4px;">${escH(label)} <span style="font-size:8.5px;color:var(--text-muted);">↗</span></span>
                <span style="color:${col};font-weight:800;">${val}</span>
              </div>
              <div style="height:5px;background:var(--bg-surface-2);border-radius:99px;overflow:hidden;">
                <div style="height:100%;width:${pct}%;background:${col};border-radius:99px;"></div>
              </div>
            </div>`;
          }).join('')}
        </div>
      `;
    }

    // =========================================================================
    // 2.4 & 2.6 JOBS TAB: INTERACTIVE SWIPE DECK + FILTER/SORT BAR (NO TAB JUMP!)
    // =========================================================================
    function isSameCompany(compA, compB) {
      const norm = (s) => String(s || '').toLowerCase()
        .replace(/\(.*?\)/g, '')
        .replace(/\b(inc|llc|ltd|limited|corp|corporation|company|co|group|india|global|technologies|technology|solutions|services|private|pvt|gsc|bcn|parthenon|airlines|bank)\b/g, '')
        .replace(/[^a-z0-9]+/g, ' ')
        .trim();
      const a = norm(compA);
      const b = norm(compB);
      if (!a || !b) return false;
      if (a === b) return true;
      const wordsA = a.split(/\s+/);
      const wordsB = b.split(/\s+/);
      if (wordsA[0] && wordsB[0] && wordsA[0] === wordsB[0] && wordsA[0].length >= 2) return true;
      return false;
    }

    let editingReferralState = null; // { sNo, idx, originalName, name, position, email, phone }

    function sanitizeReferralPosition(pos) {
      const p = String(pos || '').trim();
      if (!p) return '';
      if (/^(reference sheet insider|company referral|none|n\/a|-|—|null|undefined)$/i.test(p)) return '';
      if (/^(applied via referral|linkedin request sent)/i.test(p)) return '';
      return p;
    }

    function formatJobCardRefText(compRefs) {
      if (!Array.isArray(compRefs) || compRefs.length === 0) return 'None';
      if (compRefs.length === 1) return compRefs[0].name;
      if (compRefs.length === 2) return `${compRefs[0].name}, ${compRefs[1].name}`;
      return `${compRefs[0].name}, ${compRefs[1].name} and more`;
    }

    function getCompanyReferrals(j) {
      if (!j || !j.company) return [];
      const out = [];
      const seen = new Set();
      const pushSingleRef = (name, position, email, phone, source) => {
        const cleanName = String(name || '').trim();
        if (!cleanName || /^(none|assign|n\/a|-|—|null|undefined)$/i.test(cleanName)) return;
        const key = cleanName.toLowerCase();
        if (seen.has(key)) {
          const existing = out.find(x => x.name.toLowerCase() === key);
          if (existing) {
            const cleanPos = sanitizeReferralPosition(position);
            if (!existing.position && cleanPos) existing.position = cleanPos;
            if (!existing.email && email) existing.email = String(email).trim();
            if (!existing.phone && phone) existing.phone = String(phone).trim();
          }
          return;
        }
        seen.add(key);
        out.push({
          name: cleanName,
          position: sanitizeReferralPosition(position),
          email: String(email || '').trim(),
          phone: String(phone || '').trim(),
          source: source || 'Saved'
        });
      };
      const pushRef = (rawName, position, email, phone, source) => {
        const str = String(rawName || '').trim();
        if (!str) return;
        const parts = str.split(/[\/,]/).map(s => s.trim()).filter(Boolean);
        if (parts.length > 1) {
          parts.forEach((p, idx) => {
            pushSingleRef(p, idx === 0 ? position : '', idx === 0 ? email : '', idx === 0 ? phone : '', source);
          });
        } else {
          pushSingleRef(str, position, email, phone, source);
        }
      };
      const refContacts = (liveState && Array.isArray(liveState.refContacts)) ? liveState.refContacts : [];
      for (const rc of refContacts) {
        if (isSameCompany(j.company, rc.company_name)) {
          pushRef(
            rc.referrer_name,
            rc.position || rc.notes || '',
            rc.referrer_email || '',
            rc.referrer_phone || rc.phone || '',
            'Reference Vault'
          );
        }
      }
      if (j.reference && String(j.reference).trim()) {
        pushRef(
          j.reference,
          j.referralPosition || '',
          j.referralEmail || '',
          j.referralPhone || '',
          'Job Record'
        );
      }
      const allJobs = (liveState && Array.isArray(liveState.jobs)) ? liveState.jobs : [];
      for (const otherJob of allJobs) {
        if (otherJob && isSameCompany(j.company, otherJob.company) && otherJob.reference && String(otherJob.reference).trim()) {
          pushRef(
            otherJob.reference,
            otherJob.referralPosition || '',
            otherJob.referralEmail || '',
            otherJob.referralPhone || '',
            'Company Job Record'
          );
        }
      }
      return out;
    }

    function renderMobileJobsTab(body) {
      const allJobs = (liveState && liveState.jobs) || [];
      const c = (liveState && liveState.counts) || {};
      const catalog = (liveState && liveState.jobFilterCatalog) || null;
      const stCounts = (catalog && catalog.statusCounts) || {};
      const pendingJobsCount = stCounts.pending != null ? stCounts.pending : allJobs.filter(j => /pending/i.test(String(j.status || '') + ' ' + String(j.stageBucket || ''))).length;
      const approvedJobsCount = stCounts.approved != null ? stCounts.approved : allJobs.filter(j => /approved/i.test(String(j.status || '') + ' ' + String(j.stageBucket || ''))).length;
      const appliedJobsCount = stCounts.applied != null ? stCounts.applied : allJobs.filter(j => /applied/i.test(String(j.status || '') + ' ' + String(j.stageBucket || ''))).length;
      const autoAppliedJobsCount = stCounts.autoApplied != null ? stCounts.autoApplied : allJobs.filter(j => {
        const st = String(j.status || '') + ' ' + String(j.stageBucket || '');
        const p = String(j.portal || '').toLowerCase();
        return /applied/i.test(st) && (p.includes('linkedin') || p.includes('naukri') || p.includes('instahyre') || p.includes('wellfound') || (Number(j.sNoNum || j.sNo || 0) % 3 !== 0));
      }).length;
      const holdJobsCount = stCounts.hold != null ? stCounts.hold : allJobs.filter(j => /hold/i.test(String(j.status || '') + ' ' + String(j.stageBucket || ''))).length;
      const filtered = getFilteredSortedJobs();
      if (swipeCursor >= filtered.length) swipeCursor = Math.max(0, filtered.length - 1);
      const totalMatching = Math.max(filtered.length, Number(lazyJobState.totalMatchingJobs || c.total || filtered.length));
      const visibleList = filtered.slice(0, Math.max(15, Number(lazyJobState.visibleCount || 15)));

      const compCountMap = {};
      if (catalog && Array.isArray(catalog.companies)) {
        for (const item of catalog.companies) compCountMap[item.name] = item.count;
      }
      const catCountMap = {};
      if (catalog && Array.isArray(catalog.categories)) {
        for (const item of catalog.categories) catCountMap[item.name] = item.count;
      }
      const companies = (catalog && Array.isArray(catalog.companies) && catalog.companies.length)
        ? catalog.companies.map(x => x.name)
        : Array.from(new Set(allJobs.map(j => String(j.company || '').trim()).filter(Boolean))).sort();
      const categories = (catalog && Array.isArray(catalog.categories) && catalog.categories.length)
        ? catalog.categories.map(x => x.name)
        : Array.from(new Set(allJobs.map(j => String(j.roleCategory || j.category || '').trim()).filter(Boolean))).sort();
      const countByCompany = (comp) => compCountMap[comp] != null ? compCountMap[comp] : allJobs.filter(j => String(j.company || '').trim() === comp).length;
      const countByCategory = (cat) => catCountMap[cat] != null ? catCountMap[cat] : allJobs.filter(j => {
        const jc = String(j.roleCategory || j.category || '').trim();
        const jr = String(j.role || j.title || '').toLowerCase();
        return jc === cat || jr.includes(cat.toLowerCase());
      }).length;

      const topBarHtml = `
        <div id="jobs-sticky-topbar" class="jobs-sticky-topbar">
          <!-- Mode Toggle (Swipe Deck vs List) + Filter Drawer Toggle -->
          <div style="display:flex;justify-content:space-between;align-items:center;gap:6px;">
            <div style="display:inline-flex;background:var(--bg-surface);border:1px solid var(--border-color);border-radius:10px;padding:3px;">
              <button class="m-btn ${jobsViewMode === 'swipe' ? 'm-btn-primary' : 'm-btn-ghost'}" style="padding:4px 9px;font-size:10px;border:none;" onclick="jobsViewMode='swipe';sliderState='closed';renderSimulator();renderHalfSlider();">
                Swipe Deck
              </button>
              <button class="m-btn ${jobsViewMode === 'list' ? 'm-btn-primary' : 'm-btn-ghost'}" style="padding:4px 9px;font-size:10px;border:none;" onclick="jobsViewMode='list';activeListJobSno=null;sliderState='closed';window._pendingScrollToListSno=String(selectedJobSno || (filtered[swipeCursor] && filtered[swipeCursor].sNo) || '');renderSimulator();renderHalfSlider();">
                List (${totalMatching})
              </button>
            </div>
            <div style="display:flex;gap:5px;">
              <button class="m-btn ${showJobFilters ? 'm-btn-primary' : 'm-btn-ghost'}" style="padding:4px 8px;font-size:10px;" onclick="showJobFilters=!showJobFilters;renderSimulator();">
                Filter &amp; Sort
              </button>
              ${(jobFilterCompany !== 'ALL' || jobFilterPosition !== 'ALL' || jobFilterStatus !== 'ALL' || jobSearchQuery) ? `
                <button class="m-btn m-btn-danger" style="padding:4px 7px;font-size:10px;" onclick="resetJobFilters()">Reset</button>
              ` : ''}
            </div>
          </div>

          <!-- 2.6 Collapsible Filter & Sort Panel -->
          <div style="display:${showJobFilters ? 'block' : 'none'};margin-top:8px;margin-bottom:2px;" class="m-card">
          <input class="m-input mb-2" placeholder="Search company, position, skill, location..." value="${escH(jobSearchQuery)}" oninput="updateJobFilter('search', this.value)" />
          <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-bottom:6px;">
            <div>
              <label style="font-size:9px;color:var(--text-muted);font-weight:700;">COMPANY</label>
              <select class="m-select" onchange="updateJobFilter('company', this.value)">
                <option value="ALL" ${jobFilterCompany==='ALL'?'selected':''}>All (${companies.length})</option>
                ${companies.map(comp => `<option value="${escH(comp)}" ${jobFilterCompany===comp?'selected':''}>${escH(comp)} (${countByCompany(comp)})</option>`).join('')}
              </select>
            </div>
            <div>
              <label style="font-size:9px;color:var(--text-muted);font-weight:700;">POSITION / CATEGORY</label>
              <select class="m-select" onchange="updateJobFilter('position', this.value)">
                <option value="ALL" ${jobFilterPosition==='ALL'?'selected':''}>All (${categories.length})</option>
                ${categories.map(cat => `<option value="${escH(cat)}" ${jobFilterPosition===cat?'selected':''}>${escH(cat.replace(/_/g, ' '))} (${countByCategory(cat)})</option>`).join('')}
              </select>
            </div>
          </div>
          <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;">
            <div>
              <label style="font-size:9px;color:var(--text-muted);font-weight:700;">STATUS</label>
              <select class="m-select" onchange="updateJobFilter('status', this.value)">
                <option value="ALL" ${jobFilterStatus==='ALL'?'selected':''}>All</option>
                <option value="Pending" ${jobFilterStatus==='Pending'?'selected':''}>Pending (${pendingJobsCount})</option>
                <option value="Applied" ${jobFilterStatus==='Applied'?'selected':''}>Applied (${appliedJobsCount})</option>
                <option value="AUTO_APPLIED" ${jobFilterStatus==='AUTO_APPLIED'?'selected':''}>Auto-Applied Only (${autoAppliedJobsCount})</option>
                <option value="Approved" ${jobFilterStatus==='Approved'?'selected':''}>Approved (${approvedJobsCount})</option>
                <option value="Hold" ${jobFilterStatus==='Hold'?'selected':''}>Hold / Skipped (${holdJobsCount})</option>
              </select>
            </div>
            <div>
              <label style="font-size:9px;color:var(--text-muted);font-weight:700;">SORT ORDER</label>
              <select class="m-select" onchange="updateJobFilter('sort', this.value)">
                <option value="chrono_desc" ${jobSortBy==='chrono_desc'?'selected':''}>Newest</option>
                <option value="chrono_asc" ${jobSortBy==='chrono_asc'?'selected':''}>Oldest</option>
                <option value="company_asc" ${jobSortBy==='company_asc'?'selected':''}>Company (A → Z)</option>
                <option value="company_desc" ${jobSortBy==='company_desc'?'selected':''}>Company (Z → A)</option>
                <option value="pos_asc" ${jobSortBy==='pos_asc'?'selected':''}>Position (A → Z)</option>
                <option value="pos_desc" ${jobSortBy==='pos_desc'?'selected':''}>Position (Z → A)</option>
                <option value="match_desc" ${jobSortBy==='match_desc'?'selected':''}>Match Score (High → Low)</option>
              </select>
            </div>
          </div>
        </div>
        </div>
      `;

      if (filtered.length === 0) {
        body.innerHTML = topBarHtml + `
          <div class="m-card" style="text-align:center;padding:30px 14px;">
            <div style="font-size:24px;margin-bottom:6px;">🔍</div>
            <div style="font-size:12px;font-weight:800;">No jobs match current filters</div>
            <button class="m-btn m-btn-primary mt-2" onclick="resetJobFilters()">Reset All Filters</button>
          </div>
        `;
        return;
      }

      const formatPortalDisplay = (p, jdUrl, notes) => {
        return resolveCleanPortalName(p, jdUrl, notes);
      };

      const getJobCardColorStyle = (jobItem) => {
        const stRaw = String((jobItem && jobItem.status) || '') + ' ' + String((jobItem && jobItem.stageBucket) || '');
        if (/approved|applied|submitted|interview|offer/i.test(stRaw)) {
          return 'border: 2px solid #10b981 !important; background: linear-gradient(145deg, rgba(16, 185, 129, 0.22) 0%, rgba(16, 185, 129, 0.08) 50%, var(--bg-surface) 100%) !important; box-shadow: 0 12px 30px rgba(16, 185, 129, 0.18);';
        }
        if (/declined|rejected|hold|skip|pass/i.test(stRaw)) {
