        `;
        setTimeout(attachSwipeTouchHandlers, 20);
      } else {
        // COMPACT LIST VIEW (All items rendered in original order; single active card selection + bold active border)
        const prevListScrollTop = body.scrollTop || 0;
        if (activeListJobSno) {
          selectedJobSno = String(activeListJobSno);
        }
        body.innerHTML = topBarHtml + `

          ${visibleList.map(j => {
