                  <div style="display:flex;flex-direction:column;align-items:flex-end;gap:6px;flex-shrink:0;">
                    <div style="display:flex;gap:4px;align-items:center;">
                      <button type="button" onclick="event.stopPropagation();openJobDocumentView('${j.sNo}', 'resume');" style="cursor:pointer;font-size:9px;padding:3px 7px;border-radius:6px;background:var(--success-soft);color:var(--success);font-weight:800;border:1px solid rgba(16,185,129,0.35);min-height:24px;">CV ${rel.resumeScore}%</button>
                      <button type="button" onclick="event.stopPropagation();openJobDocumentView('${j.sNo}', 'cl');" style="cursor:pointer;font-size:9px;padding:3px 7px;border-radius:6px;background:var(--primary-soft);color:var(--primary);font-weight:800;border:1px solid rgba(99,102,241,0.35);min-height:24px;">CL ${rel.clScore}%</button>
                    </div>
                    <div style="display:flex;gap:6px;align-items:center;justify-content:flex-end;width:100%;">
