                      <button type="button" onclick="event.stopPropagation();triggerDeckSwipe('right', '${j.sNo}');" style="cursor:pointer;flex:1;display:inline-flex;align-items:center;justify-content:center;font-size:11px;font-weight:900;padding:3px 8px;border-radius:6px;background:rgba(16,185,129,0.16);color:#10b981;border:1px solid rgba(16,185,129,0.45);min-height:24px;" title="Approve Job">✓</button>
