          }).join('')}
          ${(visibleList.length < totalMatching || lazyJobState.hasMoreJobs) ? `
            <div id="lazy-load-more-sentinel" style="padding:8px 2px 18px;text-align:center;">
              <button id="lazy-load-more-btn" type="button" class="m-btn m-btn-ghost" onclick="loadMoreJobsBatch(5, false)" style="width:100%;padding:9px 12px;font-size:10.5px;font-weight:800;border-radius:10px;border:1px dashed var(--accent);color:var(--accent);background:rgba(56,189,248,0.08);" ${lazyJobState.loadingMore ? 'disabled' : ''}>
                ${lazyJobState.loadingMore ? '⏳ Loading more jobs...' : '⬇️ Load More Jobs'}
              </button>
            </div>
          ` : `
            <div style="padding:8px 2px 16px;text-align:center;font-size:10px;color:var(--text-muted);font-weight:700;">
