    function getFilteredRulesForScope(scope) {
      const rawRules = (liveState && Array.isArray(liveState.rules)) ? liveState.rules : [];
      const seen = new Set();
      const out = [];
      for (const r of rawRules) {
        const txt = String(r?.text || r?.rule_instruction || '').trim();
        if (!txt) continue;
        const cat = String(r?.category || r?.section_name || 'global').trim().toLowerCase();
        const normTxt = txt.toLowerCase().replace(/\s+/g, ' ');
        if (seen.has(normTxt)) continue;
        const rScope = classifyRuleScope(r);
        let matches = false;
        if (scope === 'cv') {
          matches = (rScope === 'cv');
        } else if (scope === 'cl') {
          matches = (rScope === 'cl' || (cat === 'heading' && txt.toLowerCase().includes('cover letter')));
        } else if (scope === 'email') {
          matches = (rScope === 'email' || cat.includes('notification'));
        } else if (scope === 'message') {
          matches = (rScope === 'message' || (rScope === 'chat' && txt.toLowerCase().includes('outreach')));
        } else if (scope === 'chat') {
          matches = (rScope === 'chat');
        } else {
          matches = true;
        }
        if (matches) {
          seen.add(normTxt);
          out.push(r);
        }
      }
      return out;
    }

    function getRuleShortSummaryTitle(r) {
      const raw = String(r?.text || r?.rule_instruction || '').trim();
      if (!raw) return 'Custom Rule';
      const low = raw.toLowerCase();
      if (low.includes('linkedin profile') && low.includes('hyperlink')) return 'Include LinkedIn Profile & Hyperlink';
      if (low.includes('contact phone number') || low.includes('8802444912')) return 'Primary Contact Phone (+91-8802444912)';
      if (low.includes('no company names or positions')) return 'No Company Names or Titles in Summary';
      if (low.includes('80/20 grounded experience')) return '80/20 Grounded Experience & JD Summary';
      if (low.includes('no statistics or numerical metrics')) return 'No Numerical Statistics in Summary';
      if (low.includes('keep summary strictly to 3-4 sentences')) return 'Concise 3–4 Sentence Summary Format';
      if (low.includes('1-page bullet budget') || low.includes('highspring india must have 3 bullets')) return '1-Page Bullet Budget & Impact Metrics';
      if (low.includes('customer support representative role')) return 'Include Customer Support Role for Analytics';
      if (low.includes('entrepreneurial leadership')) return 'Preserve Entrepreneurial Leadership Experience';
      if (low.includes('do not include marketing or tvc')) return 'No TVC/Marketing Projects in Data Roles';
      if (low.includes('marketing projects') && low.includes('grofers')) return 'Omit Marketing Projects Unless Marketing Role';
      if (low.includes('only include skills present in the google sheet')) return 'Group Master Skills into 3–4 Categories';
      if (low.includes('exclude power bi for 7-eleven')) return 'Exclude Power BI & Use Title Case Skills';
      if (low.includes('do not mention power bi')) return 'Exclude Power BI Unless in Master Skills';
      if (low.includes('title case') && low.includes('skill')) return 'Format All Core Skills in Title Case';
      if (low.includes('top 2-3 most relevant certifications')) return 'Top 2–3 Relevant Certifications Only';
      if (low.includes('260-320 words') || low.includes('justified business letter')) return '1-Page Human-Tone Cover Letter Format';
      if (low.includes('short, impactful & human-like')) return 'Short, Human-Like Comments & Notes';
      if (low.includes('super short human comment')) return 'Super Short Peer Comments (<11 Words)';
      if (low.includes('approved pattern')) return 'Poised Analytical Comment Pattern';
      if (low.includes('match post sentiment first')) return 'Match Post Sentiment in 1 Short Sentence';

      const colonIdx = raw.indexOf(':');
      if (colonIdx > 3 && colonIdx < 95) {
        let prefix = raw.slice(0, colonIdx).trim();
        prefix = prefix
          .replace(/^(?:HEADING|SUMMARY|CORE_SKILLS|SKILLS|EXPERIENCE|COVER_LETTER|LINKEDIN\s+POST|LINKEDIN\s+COMMENTS\s*&\s*OUTREACH|GLOBAL)\s*[\u2014\-:]\s*/i, '')
          .replace(/\bDIRECTIVE\b/gi, '')
          .replace(/\bMANDATORY\s+RESUME\s+LLM\b/gi, '')
          .replace(/\bAFTER\s+SUMMARY\s+HEADING\b/gi, 'in Summary')
          .replace(/\bHEADING\b/gi, 'Contact Line')
          .replace(/\s{2,}/g, ' ')
          .trim();
        if (prefix.length > 4) {
          return prefix.toLowerCase().replace(/\b\w/g, c => c.toUpperCase());
        }
      }
      let firstSentence = raw
        .replace(/^(?:HEADING|SUMMARY|SKILLS|EXPERIENCE|COVER_LETTER)\s*[\u2014\-:]\s*/i, '')
        .replace(/\bheading\b/gi, 'contact line')
        .split(/(?:\.\s|;\s)/)[0]
        .trim();
      if (firstSentence.length > 52) {
        firstSentence = firstSentence.slice(0, 49).trim() + '...';
      }
      return firstSentence;
    }

