    async function applyRuleFromModal(ruleId, mode) {
      const k = String(ruleId);
      const r = ((liveState && liveState.rules) || []).find(x => String(x.id) === k);
      if (!r) return;
      const promptText = String(r.text || r.rule_instruction || '').trim();
      const cat = String(r.category || r.section_name || 'whole_doc').toLowerCase();
      const scope = rulesModalState.scope || (a4DocType === 'cl' ? 'cl' : 'cv');
      const docType = (scope === 'cl' || a4DocType === 'cl') ? 'cl' : 'resume';
      const j = getSelectedJob();
      const targetSno = String(j?.sNo || selectedJobSno || '1');

      let sec = 'whole_doc';
      if (cat.includes('heading')) sec = 'heading';
      else if (cat.includes('summary')) sec = 'summary';
      else if (cat.includes('skill')) sec = 'skills';
      else if (cat.includes('experience')) sec = 'experience';
      else if (cat.includes('certif')) sec = 'certifications';
      else if (cat.includes('educat')) sec = 'education';
      else if (cat.includes('hobb')) sec = 'hobbies';

      closeRulesModal();
      sliderState = 'closed';
      currentPhoneTab = 'a4';
      a4DocType = docType;

      const modeLabels = {
        'SINGLE': `Working on ${j?.company || 'current'} ${docType === 'cl' ? 'Cover Letter' : 'Resume'}...`,
        'FROM_NOW_ON': `Saving rule for future ${docType === 'cl' ? 'Cover Letters' : 'Resumes'} from now on...`,
        'PREVIOUS_ONES': `Applying rule across previous ${docType === 'cl' ? 'Cover Letters' : 'Resumes'}...`,
        'ALL_DOCS': `Applying rule to all previous & future ${docType === 'cl' ? 'Cover Letters' : 'Resumes'}...`
      };
      showDocWorkingOverlay(modeLabels[mode] || 'Working on document...', getRuleShortSummaryTitle(r));

      if (mode === 'SINGLE' || mode === 'ALL_DOCS' || mode === 'FROM_NOW_ON') {
        applyClientAiRewriteToJob(j, docType, sec, promptText);
      }
      if ((mode === 'PREVIOUS_ONES' || mode === 'ALL_DOCS') && liveState && Array.isArray(liveState.jobs)) {
        liveState.jobs.forEach(jobItem => applyClientAiRewriteToJob(jobItem, docType, sec, promptText));
      }
      renderSimulator();
      renderHalfSlider();

      const apiScope = mode === 'SINGLE' ? 'ONE_OFF' : mode;
      try {
        const resp = await fetch('/webhook/job-dashboard-api', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            action: 'rewrite_doc',
            sNo: targetSno,
            docType,
            section: sec,
            feedback: promptText,
            scope: apiScope
          })
        });
        hideDocWorkingOverlay();
        if (resp.ok) {
          const resData = await resp.json();
          if (resData && resData.rules && liveState) liveState.rules = resData.rules;
          const rw = resData && resData.rewrittenDoc;
          if (rw) {
            const updateJobWithRw = (targetJob) => {
              if (!targetJob) return;
              if (!targetJob.sections) targetJob.sections = {};
              if (!targetJob.resumeSections) targetJob.resumeSections = {};
              if (!targetJob.clSections) targetJob.clSections = {};
              if (rw.docType === 'cl' && rw.clSections) {
                if (rw.headingHtml) targetJob.clSections.heading_html = rw.headingHtml;
                Object.assign(targetJob.clSections, rw.clSections);
                targetJob.clHtml = getFullCoverLetterHtml(targetJob);
              } else if (rw.resumeSections) {
                if (rw.headingHtml) {
                  targetJob.sections.heading_html = rw.headingHtml;
                  targetJob.resumeSections.heading_html = rw.headingHtml;
                }
                Object.assign(targetJob.resumeSections, rw.resumeSections);
                if (rw.resumeSections.summary_html) targetJob.sections.summary = rw.resumeSections.summary_html;
                if (rw.resumeSections.skills_html) targetJob.sections.skills_html = rw.resumeSections.skills_html;
                if (rw.resumeSections.experience_html) targetJob.sections.exp1_bullets = rw.resumeSections.experience_html;
              }
            };
            const liveJobAfter = (liveState && Array.isArray(liveState.jobs))
              ? liveState.jobs.find(x => String(x.sNo) === targetSno)
              : null;
            if (liveJobAfter) updateJobWithRw(liveJobAfter);
            if (j && j !== liveJobAfter) updateJobWithRw(j);
          }
          window._justReplacedDocInfo = { sNo: targetSno, docType, saveRule: mode !== 'SINGLE', at: Date.now() };
          scheduleClearRegeneratedBanner();
          window._pendingScrollA4ToTop = true;
          renderSimulator();
          renderHalfSlider();
          renderGlobalModals();
          const doneMsg = mode === 'SINGLE'
            ? (docType === 'cl' ? 'Cover Letter regenerated!' : 'Resume regenerated!')
            : (mode === 'FROM_NOW_ON'
                ? `✅ Rule active for all future ${docType === 'cl' ? 'CL' : 'CV'} generations from now on!`
                : (mode === 'PREVIOUS_ONES'
                    ? `✅ Applied rule across previous ${docType === 'cl' ? 'CLs' : 'CVs'}!`
                    : `✅ Applied rule to all previous & future ${docType === 'cl' ? 'CLs' : 'CVs'}!`));
          notifyToast(doneMsg);
        }
      } catch (e) {
        hideDocWorkingOverlay();
        renderSimulator();
      }
    }

