    async function submitSliderAiRewrite(sNo, saveRule) {
      const j = getSelectedJob();
      const targetSno = String(sNo || j?.sNo || selectedJobSno || '1');
      const docType = document.getElementById('sl-ai-doc')?.value || a4DocType || 'resume';
      const section = document.getElementById('sl-ai-sec')?.value || window._savedAiSec || 'whole_doc';
      const fb = (document.getElementById('sl-ai-fb')?.value || window._savedAiFb || '').trim();
      if (!fb) {
        notifyToast('⚠️ Please enter rewrite instructions.');
        return;
      }
      window._savedAiSec = section;
      const scopeVal = saveRule ? 'LEARN' : 'ONE_OFF';

      // 1. Immediate optimistic client-side update ONLY for this single job
      applyClientAiRewriteToJob(j, docType, section, fb);
      const liveMatchBefore = (liveState && Array.isArray(liveState.jobs))
        ? liveState.jobs.find(x => String(x.sNo) === targetSno)
        : null;
      if (liveMatchBefore && liveMatchBefore !== j) {
        applyClientAiRewriteToJob(liveMatchBefore, docType, section, fb);
      }

      window._savedAiFb = '';
      const fbEl = document.getElementById('sl-ai-fb');
      if (fbEl) {
        fbEl.value = '';
        fbEl.blur();
      }
      document.getElementById('phone-frame')?.classList.remove('kb-open');

      // 2. Auto-close the half-slider and switch directly to the A4 document view so the user sees the replacement happen live
      selectedJobSno = targetSno;
      currentPhoneTab = 'a4';
      a4DocType = (docType === 'cl' ? 'cl' : 'resume');
      sliderState = 'closed';
      window._aiRegeneratingDoc = { sNo: targetSno, docType: a4DocType, saveRule: Boolean(saveRule), company: j?.company || '' };
      window._pendingScrollA4ToTop = true;
      showDocWorkingOverlay(
        `Working on ${j?.company || 'your'} ${docType === 'cl' ? 'Cover Letter' : 'Resume'}...`,
        saveRule ? 'Regenerating document & saving rule in PostgreSQL' : 'Regenerating this document with AI'
      );
      renderSimulator();
      renderHalfSlider();
      renderGlobalModals();

      notifyToast(saveRule
        ? `⏳ Regenerating ${j?.company || ''} ${docType === 'cl' ? 'Cover Letter' : 'Resume'} & saving rule in Postgres...`
        : `⏳ Regenerating ${j?.company || ''} ${docType === 'cl' ? 'Cover Letter' : 'Resume'} (this ${docType === 'cl' ? 'CL' : 'CV'} only)...`);

      try {
        const resp = await fetch('/webhook/job-dashboard-api', {
          method: 'POST',
          headers: {'Content-Type': 'application/json'},
          body: JSON.stringify({ action: 'rewrite_doc', sNo: targetSno, docType, section, feedback: fb, scope: scopeVal })
        });
        window._aiRegeneratingDoc = null;
        hideDocWorkingOverlay();
        if (resp.ok) {
          const resData = await resp.json();
          if (resData && resData.rules && liveState) {
            liveState.rules = resData.rules;
          }
          if (resData && resData.profile && liveState) {
            liveState.profile = resData.profile;
          }
          const rw = resData && resData.rewrittenDoc;
          if (rw) {
            const applyRwToJob = (targetJob) => {
              if (!targetJob) return;
              if (!targetJob.sections) targetJob.sections = {};
              if (!targetJob.resumeSections) targetJob.resumeSections = {};
              if (!targetJob.clSections) targetJob.clSections = {};
              if (rw.docType === 'cl' && rw.clSections) {
                if (rw.headingHtml) targetJob.clSections.heading_html = rw.headingHtml;
                Object.assign(targetJob.clSections, rw.clSections);
                targetJob.clHtml = getFullCoverLetterHtml(targetJob);
                targetJob.clStatus = 'Reworked via AI';
              } else if (rw.resumeSections) {
                if (rw.headingHtml) {
                  targetJob.sections.heading_html = rw.headingHtml;
                  targetJob.resumeSections.heading_html = rw.headingHtml;
                }
                Object.assign(targetJob.resumeSections, rw.resumeSections);
                if (rw.resumeSections.summary_html) targetJob.sections.summary = rw.resumeSections.summary_html;
                if (rw.resumeSections.skills_html) targetJob.sections.skills_html = rw.resumeSections.skills_html;
                if (rw.resumeSections.experience_html) targetJob.sections.exp1_bullets = rw.resumeSections.experience_html;
                targetJob.resumeStatus = 'Reworked via AI';
              }
              targetJob._lastRewrittenAt = Date.now();
            };

            const liveJobAfter = (liveState && Array.isArray(liveState.jobs))
              ? liveState.jobs.find(x => String(x.sNo) === targetSno)
              : null;
            const currentSelected = getSelectedJob();
            if (liveJobAfter) applyRwToJob(liveJobAfter);
            if (currentSelected && currentSelected !== liveJobAfter && String(currentSelected.sNo) === targetSno) {
              applyRwToJob(currentSelected);
            }
            if (j && j !== liveJobAfter && j !== currentSelected) {
              applyRwToJob(j);
            }

            selectedJobSno = targetSno;
            currentPhoneTab = 'a4';
            a4DocType = (rw.docType === 'cl' ? 'cl' : 'resume');
            sliderState = 'closed';
            window._justReplacedDocInfo = { sNo: targetSno, docType: a4DocType, saveRule: Boolean(saveRule), at: Date.now() };
            scheduleClearRegeneratedBanner();
            window._pendingScrollA4ToTop = true;

            renderSimulator();
            renderHalfSlider();
            renderGlobalModals();
            if (fullPdfModalState.open) triggerA4FitPasses();

            notifyToast(docType === 'cl' ? 'Cover Letter regenerated!' : 'Resume regenerated!');
          } else {
            renderSimulator();
            renderHalfSlider();
            renderGlobalModals();
          }
        } else {
          renderSimulator();
          renderHalfSlider();
        }
      } catch (e) {
        window._aiRegeneratingDoc = null;
        hideDocWorkingOverlay();
        renderSimulator();
        renderHalfSlider();
      }
    }

