    function completePortalGoogleAuth(pid, emailStr, openTab) {
      const p = portalVaultState.find(x => x.id === pid);
      if (!p) return;
      const chosenEmail = String(emailStr || p.account || 'user@example.com').trim();
      p.account = chosenEmail;
      p.status = 'CONNECTED';
      p.everLoggedIn = true;
      p.operationsPaused = false;
      p.lastSync = 'Just now';
      p.atsType = 'Google OAuth 2.0 (' + chosenEmail + ')';
      openPortalAuthIds[pid] = false;
      closePortalGoogleAuthModal();
      updateCompanionMetrics();
      notifyToast(`Authenticated ${formatPortalCleanName(p.name)} with Google (${chosenEmail})!`);
      renderSimulator();
      if (openTab) {
        openExternalPortalUrl(getPortalTargetUrl(p), null, pid);
      }
    }

    function authorizePortalWithCredentials(pid) {
      const p = portalVaultState.find(x => x.id === pid);
      if (!p) return;
      const emailEl = document.getElementById('p-auth-email-' + pid);
      const emailVal = emailEl ? String(emailEl.value || '').trim() : '';
      if (emailVal) p.account = emailVal;
      authorizePortalNow(pid, 'Saved Credentials');
