            const isApproved = Boolean(m.congratulated || m.status === 'Commented');
            const isRejected = Boolean(m.ignored || m.status === 'Ignored');
            const hasRuleLearnt = Boolean(m.rule_learnt);
            const isCardActive = String(activeLiMsId || '') === msId;
