                <div style="display:flex;gap:6px;" onclick="event.stopPropagation();">
                  <button type="button" class="m-btn m-btn-success" style="flex:1;" onclick="event.stopPropagation();handleMilestoneAction('${escH(msId)}', 'comment')">
                    <i class="bi bi-chat-dots"></i> Comment
