    async function submitSliderLiAiRewrite(id, saveRule) {
      const fb = document.getElementById('sl-li-fb-input')?.value || 'Keep it under 10 words and natural';
      const rawLogs = (liveState && (liveState.liLogs || liveState.linkedin)) || [];
      const meta = parseLiInsiderMeta(getSelectedLiPost());
      const first = String(meta.name || 'there').split(' ')[0];
      const comp = String(meta.company || 'your team').split('/')[0].trim();
      let rewritten = '';
      if (/question/i.test(fb)) {
        rewritten = `Great point, ${first}—how is this shaping analytics priorities at ${comp}?`;
      } else if (/warm|conversational/i.test(fb)) {
        rewritten = `Really enjoyed reading this, ${first}! Always great seeing how ${comp} approaches analytics.`;
      } else if (/9 words|short|punch/i.test(fb)) {
        rewritten = `Spot on, ${first}—clean data foundations always win.`;
      } else {
        rewritten = `${first}, ${fb.replace(/^(make it|say|write)\s+/i, '')} — really resonates with how ${comp} scales analytics.`;
      }
      rawLogs.forEach(item => {
        if (String(item.activity_id || item.id) === String(id)) {
          item.content_text = rewritten;
          item.draftedContent = rewritten;
          if (saveRule) {
            item.rule_scope = 'Global Learned Rule';
            item.learned_rule_feedback = fb;
            if (!/approved|reject/i.test(String(item.approval_status || item.approvalStatus || ''))) {
              item.approval_status = 'Reworked & Rule Learned';
              item.approvalStatus = 'Reworked & Rule Learned';
            }
          }
        }
      });
      notifyToast(saveRule ? `✨ Rewrote draft for ${meta.name} & saved Learned Rule!` : `✨ Rewrote draft for ${meta.name}!`);
      renderSimulator();
      renderHalfSlider();
      try {
        await fetch('/webhook/job-dashboard-api', {
          method: 'POST',
          headers: {'Content-Type': 'application/json'},
          body: JSON.stringify({ action: 'li_action', activityId: id, subAction: 'feedback_rewrite', feedback: fb, learnRule: Boolean(saveRule) })
        });
      } catch (e) {}
    }

    async function submitMobileLiFeedback(id) {
