      const customText = document.getElementById('li-ms-draft-input-' + msId)?.value || m.draft;
      m.draft = customText;
      if (act === 'comment') {
        m.congratulated = true;
        m.ignored = false;
        m.status = 'Commented';
        try { navigator.clipboard.writeText(customText); } catch (e) {}
        notifyToast(`💬 Commented on ${m.person_name}'s post!`);
      } else {
        m.ignored = true;
