function resolveCleanPortalName(rawPortal, jdUrl, generalNotes) {
  const raw = String(rawPortal || '').trim();
  const rawLow = raw.toLowerCase();
  const url = String(jdUrl || '').toLowerCase();
  const notes = String(generalNotes || '').toLowerCase();

  // 1. If URL itself is on a specific job portal, always use that portal name
  if (url.includes('naukrigulf.com')) return 'Naukri Gulf';
  if (url.includes('naukri.com')) return 'Naukri';
  if (url.includes('instahyre.com')) return 'Instahyre';
  if (url.includes('wellfound.com') || url.includes('angel.co')) return 'Wellfound';
  if (url.includes('linkedin.com/jobs')) return 'LinkedIn Jobs';
  if (url.includes('indeed.com')) return 'Indeed';
  if (url.includes('cutshort.io')) return 'Cutshort';
  if (url.includes('hirist.tech') || url.includes('hirist.com')) return 'hirist';
  if (url.includes('foundit.in') || url.includes('monsterindia')) return 'foundit (Monster)';
  if (url.includes('glassdoor.')) return 'Glassdoor';
  if (url.includes('builtin.com')) return 'BuiltIn';
  if (url.includes('himalayas.app')) return 'Himalayas';
  if (url.includes('remotive.com')) return 'Remotive';
  if (url.includes('jobgether.com')) return 'Jobgether';

  // 2. Check rawPortal explicitly first (so user selection in Half-Slider is always respected)
  if (/^company\s*site$|^company\s*career\s*site$/i.test(raw)) {
    if (notes.includes('via naukri gulf')) return 'Naukri Gulf';
    if (notes.includes('via naukri') || notes.includes('naukri quick apply')) return 'Naukri';
    if (notes.includes('via instahyre')) return 'Instahyre';
    if (notes.includes('via wellfound')) return 'Wellfound';
    if (notes.includes('via linkedin')) return 'LinkedIn Jobs';
    if (notes.includes('via indeed')) return 'Indeed';
    if (notes.includes('via cutshort')) return 'Cutshort';
    if (notes.includes('via hirist')) return 'hirist';
    if (notes.includes('via foundit') || notes.includes('via monster')) return 'foundit (Monster)';
    return 'Company site';
  }

  if (rawLow.includes('naukri gulf')) return 'Naukri Gulf';
  if (rawLow.includes('naukri')) return 'Naukri';
  if (rawLow.includes('instahyre')) return 'Instahyre';
  if (rawLow.includes('wellfound')) return 'Wellfound';
  if (rawLow.includes('linkedin')) return 'LinkedIn Jobs';
  if (rawLow.includes('indeed')) return 'Indeed';
  if (rawLow.includes('cutshort')) return 'Cutshort';
  if (rawLow.includes('hirist')) return 'hirist';
  if (rawLow.includes('foundit') || rawLow.includes('monster')) return 'foundit (Monster)';
  if (rawLow.includes('glassdoor')) return 'Glassdoor';
  if (rawLow.includes('builtin')) return 'BuiltIn';
  if (rawLow.includes('himalayas')) return 'Himalayas';
  if (rawLow.includes('remotive')) return 'Remotive';
  if (rawLow.includes('jobgether')) return 'Jobgether';
  if (rawLow.includes('crossover')) return 'Crossover';
  if (rawLow.includes('turing')) return 'Turing';
  if (rawLow.includes('arc.dev')) return 'Arc.dev';
  if (rawLow.includes('iimjobs')) return 'iimjobs';
  if (rawLow.includes('shine')) return 'Shine';
  if (/referral/i.test(raw)) return 'Referral';
  if (/direct\s*email|cold\s*email|hr\s*email|^email$/i.test(raw)) return 'Direct Email';

  let cleaned = raw
    .replace(/^🤖\s*Auto-Apply\s*\((.*)\)$/i, '$1')
    .replace(/^⏳\s*Queued\s*\((.*)\)$/i, '$1')
    .replace(/^⚡\s*(?:In-Portal\s*)?Easy\s*Apply\s*\((.*)\)$/i, '$1')
    .replace(/\s*→\s*Company\s*Career\s*Site/ig, '')
    .replace(/\s*Easy\s*Apply$/i, '')
    .trim();

  if (!cleaned || /company\s*career\s*site|company\s*site/i.test(cleaned)) {
    return 'Company site';
  }
  return cleaned;
}

