const synthesizeLlmRule = (rawText, secHint, docType = 'resume') => {
  const raw = String(rawText || '').trim();
  const docLabel = docType === 'cl' ? 'Cover Letter' : (docType === 'both' ? 'Resume and Cover Letter' : 'Resume');
  const isHeading = isHeadingOrContactDirective(raw, secHint);
  const explicitNonAutoHint = (secHint && !['whole_doc', 'all', 'auto', 'global'].includes(String(secHint).trim().toLowerCase())) ? String(secHint).trim() : '';
  let resolvedSec = isHeading ? 'heading' : (explicitNonAutoHint || String(llmOut.section_name || secHint || 'global').trim());
  if (resolvedSec === 'whole_doc' || resolvedSec === 'all' || resolvedSec === 'auto') {
    if (isHeading) resolvedSec = 'heading';
    else if (docType === 'cl') resolvedSec = 'cover_letter';
    else if (/summary/i.test(raw)) resolvedSec = 'summary';
    else if (/skill/i.test(raw)) resolvedSec = 'core_skills';
    else if (/experience|bullet/i.test(raw)) resolvedSec = 'experience';
    else if (/certif/i.test(raw)) resolvedSec = 'certifications';
    else if (/educat|degree|university/i.test(raw)) resolvedSec = 'education';
    else if (/hobb|interest/i.test(raw)) resolvedSec = 'hobbies';
    else resolvedSec = 'global';
  }
  const secUpper = resolvedSec.toUpperCase();

  // Phone / Email / Heading explicit LLM-ready paraphrasing
  const detectedPh = extractPhoneFromText(raw);
  if (isHeading && detectedPh) {
    return {
      section: docType === 'cl' && String(secHint || '') !== 'heading' ? 'cover_letter' : 'heading',
      rule: `HEADING — CANDIDATE CONTACT PHONE NUMBER DIRECTIVE: In all generated ${docLabel}s for Sumanto Banerjee, ALWAYS display the candidate's primary contact phone number as ${detectedPh} in the document heading contact block (Gurgaon, India • user@example.com • ${detectedPh}); NEVER output outdated phone numbers such as +91 96504 26526 or +91-9650426526.`
    };
  }
  const detectedEm = extractEmailFromText(raw);
  if (isHeading && detectedEm) {
    return {
      section: docType === 'cl' && String(secHint || '') !== 'heading' ? 'cover_letter' : 'heading',
      rule: `HEADING — CANDIDATE CONTACT EMAIL DIRECTIVE: In all generated ${docLabel}s for Sumanto Banerjee, ALWAYS display the candidate's primary contact email address as ${detectedEm} in the document heading contact block (Gurgaon, India • ${detectedEm} • +91-8802444912).`
    };
  }

  if (llmOut.synthesized_rule && String(llmOut.synthesized_rule).trim().length > 15 && String(llmOut.synthesized_rule).trim().toLowerCase() !== raw.toLowerCase()) {
    let cleanedRule = String(llmOut.synthesized_rule).trim().replace(/^\[[a-z0-9_ -]+\]\s*:\s*/i, '');
    if (!/sumanto|resume|cover letter/i.test(cleanedRule)) {
      cleanedRule = `${cleanedRule} (Apply across Sumanto Banerjee's ${docLabel} ${resolvedSec} section.)`;
    }
    return { section: resolvedSec, rule: cleanedRule };
  }
  if (/(?:remove|no|without|exclude|omit|don't|do not|never).*(?:company|position|role|title)/i.test(raw) && (/summary/i.test(raw) || /summary/i.test(resolvedSec))) {
    return {
      section: 'summary',
      rule: 'SUMMARY — NO COMPANY NAMES OR POSITIONS AFTER SUMMARY HEADING DIRECTIVE: In all generated resume summaries, NEVER include target company names, specific target job titles, or external organizational markers after the Summary heading or inside the summary text; keep the focus entirely on grounded functional competencies, enterprise data analytics, BI automation, and stakeholder strategy.'
    };
  }
  if (/stat|number|data|1m\+|40%|percent/i.test(raw) && (/summary/i.test(raw) || /summary/i.test(resolvedSec))) {
    return {
      section: 'summary',
      rule: 'SUMMARY — NO STATISTICS OR NUMERICAL METRICS DIRECTIVE: NEVER include percentages, numbers, record volumes, or quantitative metrics (such as "1M+ monthly records", "40%", "25%–30%", "84%", or "15+ launches") in the Summary section; reserve all numerical metrics strictly for the Experience section bullets. Instead, write a qualitative 3-sentence Summary grounded in Sumanto\x27s past experience across enterprise SQL/Python analytics, Tableau BI reporting, workflow automation, and stakeholder consulting, tailored directly to the current Job Description.'
    };
  }
  const quoted = [];
  const withoutQuotes = raw.replace(/like\s*[-:]?\s*["“](.*?)["”]/gi, (_, q) => {
    quoted.push(q.trim().slice(0, 90));
    return '';
  }).replace(/["“](.*?)["”]/g, (_, q) => {
    if (q.length > 25) { quoted.push(q.trim().slice(0, 90)); return ''; }
    return `"${q}"`;
  }).trim();

  const clauses = withoutQuotes.split(/(?:\.|\n|;)+/).map(s => s.trim()).filter(Boolean);
  const formattedClauses = clauses.map(c => {
    if (/^(don't|do not|never|avoid|no\s+)/i.test(c)) {
      return 'NEVER ' + c.replace(/^(don't|do not|never|avoid|no)\s+/i, '').trim();
    }
    if (/^(use|always|include|keep|make sure|ensure|start|open|write|change|update|set|replace)\b/i.test(c)) {
      return 'ALWAYS ' + c.replace(/^always\s+/i, '').trim();
    }
    return 'MUST ' + c;
  });
  const banSuffix = quoted.length ? ` (specifically prohibit patterns such as "${quoted[0]}...")` : '';
  const bodyDirective = formattedClauses.join('; and ') || (`Follow constraint: ${withoutQuotes}`);
  return {
    section: resolvedSec,
    rule: `${secUpper} — MANDATORY ${docLabel.toUpperCase()} LLM DIRECTIVE: When generating or rewriting Sumanto Banerjee's ${docLabel} (${resolvedSec} section), ${bodyDirective}${banSuffix}. Enforce this rule strictly across all future LLM generations.`
  };
};

