// WF3 Plain-English Human Cover Letter Scrubber (Server-Side Headless Port)
const cleanHumanClParagraph = (val, fallback, companyName) => {
  let s = String(val || '').replace(/```html|```/gi, '').trim();
  if (s.length < 15) s = String(fallback || '').trim();
  if (!s) return '';
  s = s.replace(/<\/p>\s*<p[^>]*>/gi, ' ');
  s = s.replace(/<\/?(strong|b)>/gi, '');
  s = s.replace(/\s*—\s*/g, ', ').replace(/,\s*,/g, ',');
  const cName = String(companyName || 'the organization').trim();
  s = s.replace(/\bto your team\b/gi, `to ${cName}`);
  s = s.replace(/\bif your team uses\b/gi, `if the team at ${cName} uses`);
  s = s.replace(/\bspeaking with your team\b/gi, 'speaking with you');
  const swaps = [
    [/\bdisparate\b/gi, 'different'],
    [/\brigorous stewardship\b/gi, 'close attention to detail'],
    [/\bpractical stewardship\b/gi, 'close attention to detail'],
    [/\bstewardship\b/gi, 'care'],
    [/\brigorous\b/gi, 'careful'],
    [/\boperational funnel\b/gi, 'hiring process'],
    [/\bstructural adjustment\b/gi, 'simple change'],
    [/\bstrategic friction\b/gi, 'confusion'],
    [/\bdata hygiene\b/gi, 'data accuracy'],
    [/\bnew cohorts\b/gi, 'new joiners'],
    [/\bcohorts\b/gi, 'batches']
  ];
  for (const [pat, rep] of swaps) s = s.replace(pat, rep);
  if (!/^<p/i.test(s)) s = `<p>${s}</p>`;
  return s;
};

// WF1 1-Page A4 Visual Line Inspector (Server-Side Headless Port)
const inspectServerA4Lines = (rs) => {
  const strip = (h) => String(h || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  const cpl = 94;
  let lines = 4.5;
  lines += 1.6 + Math.max(1, Math.ceil(strip(rs?.summary_html).length / cpl));
  const sklMatches = String(rs?.skills_html || '').match(/<li[^>]*>[\s\S]*?<\/li>/gi) || [];
  lines += 1.6 + sklMatches.reduce((acc, m) => acc + Math.max(1, Math.ceil(strip(m).length / cpl)), 0);
  const expMatches = String(rs?.experience_html || '').match(/<li[^>]*>[\s\S]*?<\/li>/gi) || [];
  const jobBlocks = (String(rs?.experience_html || '').match(/class=["']job-block["']/gi) || []).length || 4;
  lines += 1.6 + (jobBlocks * 1.35) + expMatches.reduce((acc, m) => acc + Math.max(1, Math.ceil(strip(m).length / (cpl - 4))), 0);
  const certRows = (String(rs?.certifications_html || '').match(/class=["']cert-row["']/gi) || []).length || 3;
  lines += 1.6 + (certRows * 1.15);
  const est = Math.round(lines * 10) / 10;
  return {
    estimatedVisualLines: est,
    fitsSingleA4Page: est <= 54.0,
    recommendedFontPt: est > 50.0 ? '9.5pt' : '9.9pt',
    expBulletCount: expMatches.length,
    skillCategoryCount: sklMatches.length
  };
};

// Server-Side Headless JD Match & Keyword Relevance Engine
const computeServerJdMatch = (j) => {
  const jdText = `${j.title || ''} ${j.jd || ''} ${j.extractedKeywords || ''}`.toLowerCase();
  const resText = `${j.resumeSections?.summary_html || ''} ${j.resumeSections?.skills_html || ''} ${j.resumeSections?.experience_html || ''}`.replace(/<[^>]+>/g, ' ').toLowerCase();
  const clText = `${j.clSections?.para1_hook_html || ''} ${j.clSections?.para2_stewardship_html || ''} ${j.clSections?.para3_impact_story_html || ''} ${j.clSections?.para4_resilience_html || ''} ${j.clSections?.para5_closing_html || ''}`.replace(/<[^>]+>/g, ' ').toLowerCase();

  const taxonomy = [
    { label: 'SQL', rx: /\bsql\b|postgres|mysql|bigquery|snowflake/i },
    { label: 'Python', rx: /\bpython\b|pandas|numpy|scipy/i },
    { label: 'Tableau', rx: /\btableau\b/i },
    { label: 'Power BI / Looker', rx: /power\s*bi|looker|metabase|superset/i },
    { label: 'KPI & Executive Dashboards', rx: /dashboard|kpi|scorecard|wbr|mbr|qbr/i },
    { label: 'Data Modeling & ETL', rx: /etl|pipeline|warehouse|data model|schema|dbt/i },
    { label: 'Funnel & Cohort Analytics', rx: /funnel|cohort|retention|conversion|churn/i },
    { label: 'A/B Testing & Experimentation', rx: /a\/b|experiment|hypothesis|statistical/i },
    { label: 'Root-Cause Diagnostics', rx: /root[-\s]cause|variance|diagnostic|anomaly/i },
    { label: 'Workflow Automation', rx: /automat|n8n|airflow|scripting/i },
    { label: 'Stakeholder Consulting', rx: /stakeholder|executive|consulting|cross[-\s]functional|storytelling/i },
    { label: 'Commercial & Revenue Strategy', rx: /revenue|pricing|commercial|monetiz|growth|roi/i },
    { label: 'Data Governance & QA', rx: /governance|quality|qa|accuracy|reconciliat|sla/i },
    { label: 'Excel & Financial Modeling', rx: /excel|spreadsheet|financial|forecast/i }
  ];

  const jdRelevant = taxonomy.filter(t => t.rx.test(jdText));
  const activePool = jdRelevant.length >= 4 ? jdRelevant : taxonomy.slice(0, 8);
  const matchedKeywords = [];
  const missingKeywords = [];
  let resHits = 0;
  let clHits = 0;

  for (const item of activePool) {
    const inRes = item.rx.test(resText);
    const inCl = item.rx.test(clText);
    if (inRes) {
      matchedKeywords.push(item.label);
      resHits++;
    } else {
      missingKeywords.push(item.label);
    }
    if (inCl || inRes) clHits += inCl ? 1 : 0.7;
  }

  const ratioRes = activePool.length > 0 ? (resHits / activePool.length) : 0.9;
  const ratioCl = activePool.length > 0 ? (clHits / activePool.length) : 0.88;
  const seed = (Number(j.sNoNum || 1) * 7) % 5;
  const resumeScore = Math.min(98, Math.max(82, Math.round(78 + ratioRes * 18 + seed * 0.5)));
  const clScore = Math.min(97, Math.max(80, Math.round(76 + ratioCl * 18 + seed * 0.4)));
  const overallScore = Math.round((resumeScore * 0.65) + (clScore * 0.35));

  return {
    resumeScore,
    clScore,
    overallScore,
    matchedKeywords: matchedKeywords.slice(0, 10),
    missingKeywords: missingKeywords.slice(0, 4)
  };
};

