if (action === 'init_db_audit_monitor') {
  sqlQueries.push(`
    CREATE TABLE IF NOT EXISTS database_audit_log (
      id BIGSERIAL PRIMARY KEY,
      event_time TIMESTAMPTZ DEFAULT NOW(),
      table_name TEXT,
      operation TEXT,
      record_id TEXT,
      summary TEXT,
      changed_fields JSONB DEFAULT '{}'::jsonb,
      sql_query TEXT
    );

    CREATE OR REPLACE FUNCTION careerpulse_audit_trigger_fn() RETURNS trigger AS $body$
    DECLARE
      rec_id TEXT := '';
      sum_txt TEXT := '';
      diff_obj JSONB := '{}'::jsonb;
      old_j JSONB;
      new_j JSONB;
      k TEXT;
      changed_cols TEXT[] := ARRAY[]::TEXT[];
    BEGIN
      IF (TG_OP = 'DELETE') THEN
        old_j := to_jsonb(OLD);
        rec_id := COALESCE(old_j->>'s_no', old_j->>'resume_id', old_j->>'id', old_j->>'activity_id', old_j->>'contact_id', old_j->>'site_name', old_j->>'todo_id', old_j->>'patch_id', 'row');
        sum_txt := 'Deleted from ' || TG_TABLE_NAME || ' [' || rec_id || ']' || COALESCE(' (' || COALESCE(old_j->>'company_name', old_j->>'section_name', '') || ')', '');
        diff_obj := jsonb_build_object('deleted_row', old_j);
      ELSIF (TG_OP = 'INSERT') THEN
        new_j := to_jsonb(NEW);
        rec_id := COALESCE(new_j->>'s_no', new_j->>'resume_id', new_j->>'id', new_j->>'activity_id', new_j->>'contact_id', new_j->>'site_name', new_j->>'todo_id', new_j->>'patch_id', 'row');
        sum_txt := 'Inserted into ' || TG_TABLE_NAME || ' [' || rec_id || ']' ||
                   CASE
                     WHEN new_j ? 'rule_instruction' THEN ': ' || LEFT(COALESCE(new_j->>'rule_instruction', ''), 120)
                     WHEN new_j ? 'company_name' THEN ' (' || COALESCE(new_j->>'company_name', '') || ' — ' || COALESCE(new_j->>'position_title', '') || ')'
                     ELSE ''
                   END;
        diff_obj := jsonb_build_object('inserted_row', new_j);
      ELSIF (TG_OP = 'UPDATE') THEN
        old_j := to_jsonb(OLD);
        new_j := to_jsonb(NEW);
        rec_id := COALESCE(new_j->>'s_no', new_j->>'resume_id', new_j->>'id', new_j->>'activity_id', new_j->>'contact_id', new_j->>'site_name', new_j->>'todo_id', new_j->>'patch_id', 'row');
        FOR k IN SELECT jsonb_object_keys(new_j)
        LOOP
          IF k NOT IN ('updated_at', 'last_updated') AND (old_j->k IS DISTINCT FROM new_j->k) THEN
            changed_cols := array_append(changed_cols, k);
            diff_obj := diff_obj || jsonb_build_object(k, jsonb_build_object(
              'old', LEFT(COALESCE(old_j->>k, 'NULL'), 500),
              'new', LEFT(COALESCE(new_j->>k, 'NULL'), 500)
            ));
          END IF;
        END LOOP;
        IF array_length(changed_cols, 1) IS NULL THEN
          RETURN NEW;
        END IF;
        sum_txt := 'Updated ' || TG_TABLE_NAME || ' [' || rec_id || ']' ||
                   CASE WHEN new_j ? 'company_name' THEN ' (' || COALESCE(new_j->>'company_name', '') || ')' ELSE '' END ||
                   ' — changed columns: ' || array_to_string(changed_cols, ', ');
      END IF;

      INSERT INTO database_audit_log (table_name, operation, record_id, summary, changed_fields, sql_query)
      VALUES (TG_TABLE_NAME, TG_OP, rec_id, sum_txt, diff_obj, LEFT(current_query(), 2000));

      IF (TG_OP = 'DELETE') THEN RETURN OLD; ELSE RETURN NEW; END IF;
    END;
    $body$ LANGUAGE plpgsql;

    DROP TRIGGER IF EXISTS trg_audit_job_applications ON job_applications;
    CREATE TRIGGER trg_audit_job_applications AFTER INSERT OR UPDATE OR DELETE ON job_applications FOR EACH ROW EXECUTE FUNCTION careerpulse_audit_trigger_fn();

    DROP TRIGGER IF EXISTS trg_audit_resume_generations ON resume_generations;
    CREATE TRIGGER trg_audit_resume_generations AFTER INSERT OR UPDATE OR DELETE ON resume_generations FOR EACH ROW EXECUTE FUNCTION careerpulse_audit_trigger_fn();

    DROP TRIGGER IF EXISTS trg_audit_cover_letter_generations ON cover_letter_generations;
    CREATE TRIGGER trg_audit_cover_letter_generations AFTER INSERT OR UPDATE OR DELETE ON cover_letter_generations FOR EACH ROW EXECUTE FUNCTION careerpulse_audit_trigger_fn();

    DROP TRIGGER IF EXISTS trg_audit_learned_rules ON learned_rules;
    CREATE TRIGGER trg_audit_learned_rules AFTER INSERT OR UPDATE OR DELETE ON learned_rules FOR EACH ROW EXECUTE FUNCTION careerpulse_audit_trigger_fn();

    DROP TRIGGER IF EXISTS trg_audit_linkedin_activity_log ON linkedin_activity_log;
    CREATE TRIGGER trg_audit_linkedin_activity_log AFTER INSERT OR UPDATE OR DELETE ON linkedin_activity_log FOR EACH ROW EXECUTE FUNCTION careerpulse_audit_trigger_fn();

    DROP TRIGGER IF EXISTS trg_audit_linkedin_network_contacts ON linkedin_network_contacts;
    CREATE TRIGGER trg_audit_linkedin_network_contacts AFTER INSERT OR UPDATE OR DELETE ON linkedin_network_contacts FOR EACH ROW EXECUTE FUNCTION careerpulse_audit_trigger_fn();

    DROP TRIGGER IF EXISTS trg_audit_master_resume_state ON master_resume_state;
    CREATE TRIGGER trg_audit_master_resume_state AFTER INSERT OR UPDATE OR DELETE ON master_resume_state FOR EACH ROW EXECUTE FUNCTION careerpulse_audit_trigger_fn();

    DROP TRIGGER IF EXISTS trg_audit_portal_credentials_vault ON portal_credentials_vault;
    CREATE TRIGGER trg_audit_portal_credentials_vault AFTER INSERT OR UPDATE OR DELETE ON portal_credentials_vault FOR EACH ROW EXECUTE FUNCTION careerpulse_audit_trigger_fn();

    INSERT INTO database_audit_log (event_time, table_name, operation, record_id, summary, changed_fields, sql_query)
    SELECT COALESCE(created_at, NOW()), 'learned_rules', 'INSERT', 'Rule #' || id::text,
           'Saved rule [' || COALESCE(section_name, 'global') || ']: ' || LEFT(COALESCE(rule_instruction, ''), 140),
           jsonb_build_object('section_name', section_name, 'rule_instruction', rule_instruction, 'triggered_by_comment', triggered_by_comment),
           'INSERT INTO learned_rules ...'
    FROM learned_rules
    WHERE NOT EXISTS (SELECT 1 FROM database_audit_log LIMIT 1)
    ORDER BY id DESC LIMIT 15;

    INSERT INTO database_audit_log (event_time, table_name, operation, record_id, summary, changed_fields, sql_query)
    SELECT COALESCE(updated_at, NOW()), 'resume_generations', 'UPDATE', COALESCE(resume_id, 'RES-' || s_no),
           'Generated / Updated 1-Page Resume for #' || COALESCE(s_no, '') || ' (' || COALESCE(company_name, '') || ' — ' || COALESCE(position_title, '') || ', Rev #' || COALESCE(revision_count::text, '1') || ')',
           jsonb_build_object('company_name', company_name, 'position_title', position_title, 'resume_status', resume_status, 'last_reviewer_note', last_reviewer_note),
           'INSERT INTO resume_generations ... ON CONFLICT (resume_id) DO UPDATE ...'
    FROM resume_generations
    WHERE updated_at IS NOT NULL AND (SELECT COUNT(*) FROM database_audit_log) < 20
    ORDER BY updated_at DESC LIMIT 10;

    INSERT INTO database_audit_log (event_time, table_name, operation, record_id, summary, changed_fields, sql_query)
    SELECT COALESCE(updated_at, NOW()), 'cover_letter_generations', 'UPDATE', COALESCE(resume_id, 'RES-' || s_no),
           'Generated / Updated 1-Page Cover Letter for #' || COALESCE(s_no, '') || ' (' || COALESCE(company_name, '') || ' — ' || COALESCE(position_title, '') || ', Rev #' || COALESCE(revision_count::text, '1') || ')',
           jsonb_build_object('company_name', company_name, 'position_title', position_title, 'cl_status', cl_status, 'last_review_note', last_review_note),
           'INSERT INTO cover_letter_generations ... ON CONFLICT (resume_id) DO UPDATE ...'
    FROM cover_letter_generations
    WHERE updated_at IS NOT NULL AND (SELECT COUNT(*) FROM database_audit_log) < 35
    ORDER BY updated_at DESC LIMIT 10;
  `);
  apiMessage = 'Initialized PostgreSQL database_audit_log table and row-level triggers across all tables!';
}

if (action === 'migrate_exact_urls_and_portals') {
  let migratedCount = 0;
  for (const r of rawSheetRows) {
