  const compRefs = referralsByCompany[j.company] || [];
  const matchBreakdown = computeServerJdMatch(j);
  const pageFit = inspectServerA4Lines(j.resumeSections);
  return {
    ...j,
    index: j.sNoNum || j.sNo,
    role: j.title,
    category: j.roleCategory,
    jobUrl: j.jdUrl,
    jd: body.includeFullJd ? String(j.jd || "") : String(j.jd || "").slice(0, 1400),
    jdSnippet: String(j.jd || "").slice(0, 280),
    lastUpdate: j.lastUpdated,
    referralName: j.reference || compRefs.map(r => r.referrer_name).filter(Boolean).join(', ') || '',
    referralContact: j.hrEmail || j.hrPhone || compRefs[0]?.referrer_email || compRefs[0]?.referrer_phone || '',
    referralStatus: j.generalNotes || compRefs[0]?.position || '',
