    matchBreakdown,
    pageFit,
    resumeFileId: j.resumeDriveId,
    resumeUrl: j.resumeLink,
    clFileId: j.clDriveId,
    clUrl: j.clLink,
    sections: {
      heading_html: j.resumeSections?.heading_html || computeGlobalHeading('resume'),
