// Compute deterministic State-Version ETag for zero-payload 304 caching
const rawStateSig = `${counts.total}:${counts.applied}:${counts.pendingReview}:${allLearnedRules.length}:${refContacts.length}:${productTodos.map(t => `${t.todo_id}=${t.status}:${t.is_done}`).join(',')}:${fullNameClean}:${profileFormatted.preferredLocations}:${sqlQueries.length}`;
let etagHash = 2166136261;
for (let i = 0; i < rawStateSig.length; i++) {
  etagHash ^= rawStateSig.charCodeAt(i);
  etagHash = Math.imul(etagHash, 16777619);
}
const stateVersion = `W/"cp-${(etagHash >>> 0).toString(16)}"`;
const clientEtag = String(body.ifNoneMatch || reqItem.headers?.['if-none-match'] || '').trim();
const responseMode = String(body.responseMode || 'full').trim().toLowerCase();
const shouldSyncGoogleSheets = Boolean(body.syncSheet);

