  llmApiCalls: (prepMeta.needsLlm && !llmCacheHit) ? 1 : 0,
  sheetApiCalls: shouldSyncGoogleSheets ? (sheetUpdates.length + trackerUpdates.length + liSheetUpdates.length + fhSheetUpdates.length) : 0,
  cachedPromptsCount: llmCacheRows.length,
  responseMode
};

const jobFilterCatalog = (() => {
  const compMap = {};
  const catMap = {};
  let pending = 0, applied = 0, autoApplied = 0, approved = 0, hold = 0;
  for (const j of jobs) {
    const comp = String(j.company || '').trim();
    if (comp) compMap[comp] = (compMap[comp] || 0) + 1;
    const cat = String(j.roleCategory || j.category || '').trim();
    if (cat) catMap[cat] = (catMap[cat] || 0) + 1;
    const st = String(j.status || '') + ' ' + String(j.stageBucket || '');
    const p = String(j.portal || '').toLowerCase();
    if (/pending/i.test(st)) pending++;
    if (/approved/i.test(st)) approved++;
    if (/applied/i.test(st)) {
      applied++;
      if (p.includes('linkedin') || p.includes('naukri') || p.includes('instahyre') || p.includes('wellfound') || (Number(j.sNoNum || j.sNo || 0) % 3 !== 0)) {
        autoApplied++;
      }
    }
    if (/hold/i.test(st)) hold++;
  }
  const companies = Object.keys(compMap).sort().map(name => ({ name, count: compMap[name] }));
  const categories = Object.keys(catMap).sort().map(name => ({ name, count: catMap[name] }));
  return {
    totalJobs: jobs.length,
    companies,
    categories,
    statusCounts: { pending, applied, autoApplied, approved, hold }
  };
})();

const lazyJobsResult = (() => {
  let list = jobs.slice();
  if (body.sNo && action === 'get_job_detail') {
    const sn = String(body.sNo).trim();
    const found = list.filter(x => String(x.sNo) === sn);
    if (found.length > 0) {
      return {
        items: found.map(enrichJobItem),
        pagination: { offset: 0, limit: found.length, returnedCount: found.length, totalMatchingJobs: found.length, totalAllJobs: jobs.length, hasMoreJobs: false, nextOffset: found.length }
      };
    }
  }
  if (body.companyFilter && String(body.companyFilter).trim() !== 'ALL') {
    const cf = String(body.companyFilter).trim();
    list = list.filter(x => String(x.company || '').trim() === cf);
  }
  if (body.positionFilter && String(body.positionFilter).trim() !== 'ALL') {
    const posf = String(body.positionFilter).trim();
    list = list.filter(x => {
      const cat = String(x.roleCategory || x.category || '').trim();
      const role = String(x.role || x.title || '').toLowerCase();
      return cat === posf || role.includes(posf.toLowerCase());
    });
  }
  if (body.statusFilter && String(body.statusFilter).trim() !== 'ALL') {
    const sf = String(body.statusFilter).trim();
    if (sf === 'AUTO_APPLIED') {
      list = list.filter(x => {
        const st = `${x.status} ${x.stageBucket}`;
        const p = String(x.portal || '').toLowerCase();
        return /applied/i.test(st) && (p.includes('linkedin') || p.includes('naukri') || p.includes('instahyre') || p.includes('wellfound') || (Number(x.sNoNum || x.sNo || 0) % 3 !== 0));
      });
    } else {
      const sfl = sf.toLowerCase();
      list = list.filter(x => `${x.status} ${x.stageBucket}`.toLowerCase().includes(sfl));
    }
  }
  if (body.portalFilter && String(body.portalFilter).trim() !== 'ALL') {
    const pf = String(body.portalFilter).toLowerCase().trim();
    list = list.filter(x => String(x.portal || '').toLowerCase().includes(pf));
  }
  if (body.searchQuery && String(body.searchQuery).trim()) {
    const q = String(body.searchQuery).toLowerCase().trim();
    list = list.filter(x => `${x.company || ''} ${x.role || x.title || ''} ${x.portal || ''} ${x.location || ''}`.toLowerCase().includes(q));
  }
  const sortBy = String(body.sortBy || 'chrono_desc').trim();
  list.sort((a, b) => {
    const snoA = Number(a.sNoNum || a.sNo || 0);
    const snoB = Number(b.sNoNum || b.sNo || 0);
    if (sortBy === 'chrono_desc') return snoB - snoA;
    if (sortBy === 'chrono_asc') return snoA - snoB;
    if (sortBy === 'company_asc') return String(a.company || '').localeCompare(String(b.company || ''));
    if (sortBy === 'company_desc') return String(b.company || '').localeCompare(String(a.company || ''));
    if (sortBy === 'pos_asc') return String(a.role || a.title || '').localeCompare(String(b.role || b.title || ''));
    if (sortBy === 'pos_desc') return String(b.role || b.title || '').localeCompare(String(a.role || a.title || ''));
    if (sortBy === 'match_desc') return Number(b.matchScore || b.relevanceScore || 0) - Number(a.matchScore || a.relevanceScore || 0);
    return snoB - snoA;
  });
  const off = Math.max(0, Number(body.offset || 0));
  const defaultLimit = action === 'load_more_jobs' ? 5 : 15;
  const lim = String(body.limit || '').toUpperCase() === 'ALL' ? list.length : (Number(body.limit) > 0 ? Number(body.limit) : defaultLimit);
  const sliced = lim > 0 ? list.slice(off, off + lim) : list;
  return {
    items: sliced.map(enrichJobItem),
    pagination: {
      offset: off,
      limit: lim,
      returnedCount: sliced.length,
      totalMatchingJobs: list.length,
      totalAllJobs: jobs.length,
      hasMoreJobs: (off + sliced.length) < list.length,
      nextOffset: off + sliced.length
    }
  };
})();

