  llmCacheKey = simpleHashKey(sig);
  if (!body.bypassCache) {
    const hit = llmCacheRows.find(r => r.cache_key === llmCacheKey);
    if (hit && hit.response_json) {
      try {
        cachedLlmOut = JSON.parse(hit.response_json);
        needsLlm = false;
        llmCacheHit = true;
      } catch (e) {}
    }
  }
}

return [{ json: { needsLlm, llmPrompt, llmCacheKey, llmCacheHit, cachedLlmOut } }];

